import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-g-001","clusterId":"G","werkstueckRef":"G.1.1","stufe":1,"question":"Beim Abendessen sagt jemand: „Du glaubst doch alles, was die Medien dir vorsetzen – du bist halt noch ein Schlafschaf, ich bin aufgewacht.“ Was bewirkt diese Wortwahl in der Auseinandersetzung vor allem?","options":["Sie zwingt dich in die Verteidigung, sodass nun du begründen musst, warum du den Medien glaubst, statt dass er seine eigene Sicht belegt.","Sie stellt dich als wehrlos schlafendes Schaf dar, das den Medien blind folgt, sodass du kaum noch als ernsthafter Gesprächspartner giltst.","Sie stellt ihn als jemanden dar, der mehr durchschaut als du, sodass seine Sicht auf die Medien als die besser informierte erscheint.","Sie heizt die Stimmung beim Essen auf, sodass ihr beide gereizter werdet, die Frage nach den Medien aber weiter offen besprochen werden kann."],"correctIndex":1,"explanation":"„Schlafschaf“ verbindet zwei Bilder: den unbewussten, wehrlosen Zustand des Schlafs und das blind folgende Schaf. Das Wort wertet ab und entmenschlicht: Wer so genannt wird, gilt nicht mehr als ernstzunehmender Gesprächspartner. Zugleich hebt „aufgewacht“ die eigene Gruppe als überlegen heraus. Der Unterschied wird so nicht als unterschiedliche Bewertung von Belegen dargestellt, sondern als unterschiedlicher „Bewusstseinszustand“. Dann lässt sich jede Kritik als Äußerung eines Schlafenden abtun, und das Gespräch über Belege erübrigt sich. Eine neutrale Einladung ist das nicht, denn gerade die Abwertung ist der Zweck des Wortes.","coreRule":"⚡ Ein Schimpfwort für Andersdenkende ist kein Argument, sondern der Ersatz dafür.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 2: Entmenschlichung der Outgroup)","status":"entwurf","scenario":"","kurz":"„Schlafschaf“ wertet dich als blind folgend ab, und „aufgewacht“ hebt ihn als überlegen heraus. Damit zählt jede Kritik als Äußerung eines Schlafenden, und der Streit geht nicht mehr um Belege, sondern um deinen angeblichen Bewusstseinszustand.","prueffrage":"Welche Belege oder Gründe für seine Sicht nennt der Sprecher, und welche für deine Sicht widerlegt er?","rueckmeldung":[{"option":0,"text":"Die Beweislast verschiebt sich tatsächlich leicht auf dich. Das ist aber eine Nebenfolge: Der Satz fordert keine Begründung, er wertet dich ab, und genau das macht ein Gespräch über Belege schwer."},{"option":2,"text":"Mit „aufgewacht“ setzt er sich tatsächlich über dich. Das beschreibt aber nur die halbe Wirkung: Zugleich wertet „Schlafschaf“ dich ab, und die Überlegenheit gilt als Bewusstseinszustand, nicht als besser belegte Sicht."},{"option":3,"text":"Gereizt kann es am Tisch durchaus werden. Der Nachsatz trägt aber nicht, denn wenn jede Kritik als Äußerung eines Schlafenden abgetan werden kann, wird über die Belege zu den Medien gar nicht mehr offen gesprochen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"82b247315d786025"}},{"id":"qx-g-002","clusterId":"G","werkstueckRef":"G.1.1","stufe":2,"question":"Welche Reaktion ist in dieser Lage am sinnvollsten?","scenario":"Du nennst einem Bekannten eine Studie, die seiner Behauptung zu einem Impfstoff widerspricht. Er winkt ab: „Das sagst du nur, weil du noch schläfst.“","options":["Auf die Studie selbst eingehen: Methode, Stichprobe und Ergebnis sachlich erläutern, bis er erkennt, dass die Belege solide sind.","Nach seinen Belegen fragen: Ihn bitten, eine Quelle für seine Behauptung zu nennen, damit ihr Studie gegen Studie vergleichen könnt.","Beiden Sichtweisen gleiches Gewicht geben: Du räumst ein, dass beide Seiten recht haben können, damit der Streit nicht eskaliert.","Den Rahmen ansprechen statt den Inhalt: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches „Erwachen“."],"correctIndex":3,"explanation":"Der Satz „Das sagst du nur, weil du noch schläfst“ wirkt wie ein Schutzschild: Er erklärt jede Kritik im Voraus für wertlos, weil sie angeblich von jemandem kommt, der die Wahrheit nicht sehen kann. Dadurch wird die Ideologie unfalsifizierbar: Kritik von außen kann per Definition ignoriert werden, weil sie ja nur von einem „Schlafenden“ kommt. Sinnvoll ist, den Rahmen sichtbar zu machen: Wissenschaftliche Erkenntnis ist meist ein langer Prozess aus Zweifeln, Testen und vorläufiger Annäherung, kein plötzliches „Erwachen“ in eine absolute Wahrheit. Hilfreich ist zudem die Frage, ob das „Aufwachen“ nicht in Wahrheit das Einschlafen in einen einfachen, befriedigenden Traum sein könnte.","coreRule":"⚡ Wenn der Rahmen das Problem ist, hilft es nicht, innerhalb des Rahmens zu antworten.","quote":"Wissenschaftliche Erkenntnis ist meist ein langer, mühsamer Prozess des Zweifelns, des Testens und der langsamen Annäherung an eine vorläufige Wahrheit.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Der Satz erklärt jede Kritik im Voraus für wertlos, weil sie angeblich von einem „Schlafenden“ kommt. Dagegen hilft, diesen Rahmen sichtbar zu machen: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches Erwachen.","prueffrage":"Was für eine Antwort oder ein Beleg würde den Bekannten überhaupt noch umstimmen können?","rueckmeldung":[{"option":0,"text":"Eine sorgfältige Erläuterung von Methode und Ergebnis ist grundsätzlich wertvoll. Hier prallt sie aber ab, denn wer jede Kritik schon vorab als Schlaf abtut, wertet auch die besten Belege nicht mehr als Argument."},{"option":1,"text":"Nach Belegen zu fragen ist meist ein guter Zug. Hier bleibt aber der Rahmen bestehen: Ein Gegenbeleg gälte weiter als Stimme einer „Schlafenden“, und eine Quelle von ihm würde als Erkenntnis des „Erwachten“ gelten."},{"option":2,"text":"Der Wunsch, den Streit zu entschärfen, ist verständlich. Auf der einen Seite steht aber eine Studie, auf der anderen nur eine Behauptung, und gleiches Gewicht gäbe dem Rahmen recht, der Kritik im Voraus entwertet."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"08b5b1d3655ced4e"}},{"id":"qx-g-003","clusterId":"G","werkstueckRef":"G.1.1","stufe":3,"question":"Was macht das Argument in diesem Gespräch unwiderlegbar, und was ist daran der Denkfehler?","options":["Er macht den Unterschied zwischen euch zu einem Bewusstseinszustand statt zu einer anderen Bewertung der Belege, sodass jede Kritik als Äußerung eines Schlafenden gilt und nichts mehr gegen ihn sprechen kann.","Er greift dich als Person an, statt auf deine Einwände gegen seine Belege einzugehen, sodass deine Kritik schon wegen deiner Person zurückgewiesen wird und nichts mehr gegen ihn sprechen kann.","Er lässt offen, was „aufgewacht“ und „schlafen“ genau heißen sollen, statt die Begriffe an prüfbaren Merkmalen festzumachen, sodass sich seine Sicht gar nicht greifen lässt und nichts mehr gegen ihn sprechen kann.","Er behandelt seine Belege als schon bewiesen, statt ihre Deutung gegen deine Einwände zu verteidigen, sodass Zweifel an ihnen von vornherein als Irrtum gelten und nichts mehr gegen ihn sprechen kann."],"correctIndex":0,"explanation":"Jonas macht den Unterschied nicht an der Bewertung von Beweisen fest, sondern an einem angeblich anderen Bewusstseinszustand. Wer „schläft“, kann die Wahrheit per Definition nicht sehen, also darf jeder Einwand ignoriert werden. Damit kann kein denkbarer Einwand und keine denkbare Beobachtung seine Sicht mehr erschüttern. Eine Behauptung, die sich gegen jede mögliche Widerlegung abschirmt, ist unfalsifizierbar und deshalb keine prüfbare Aussage mehr. Typische Signale sind Wörter wie „Schlafschaf“ oder „Systemling“, die Kritiker schon vorab als unwissend abstempeln. Ein sinnvoller Gegenzug ist, nicht um die Etikettierung zu streiten, sondern den Frame selbst zu thematisieren: In der Wissenschaft ist der Weg zur Erkenntnis kein plötzliches „Erwachen“ in eine absolute Wahrheit, sondern ein langer Prozess des Zweifelns, des Testens und der Annäherung an eine vorläufige Wahrheit.","coreRule":"⚡ Wer Kritik schon durch ein Wort als „Schlafen“ abstempelt, macht seine Sicht unwiderlegbar.","quote":"Ein „Schlafschaf“ kann die Wahrheit per Definition nicht sehen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1, Abschnitt 2 (Punkt 3: Epistemologische Immunisierung); keine Fußnote","status":"entwurf","scenario":"In einer Diskussion über ein umstrittenes Thema legt Jonas dir seine Belege vor und sagt: „Dir fehlen die Fakten gar nicht. Du bist einfach noch nicht aufgewacht, du schläfst noch. Deshalb kannst du meine Belege nicht sehen. Und was du dagegen sagst, kommt ja nur von einem Schlafenden.“","kurz":"Jonas erklärt den Streit zu einem Unterschied im Bewusstsein statt in der Bewertung der Belege. So lässt sich jeder Einwand als Äußerung eines „Schlafenden“ abtun, und nichts kann seine Sicht mehr erschüttern. Das macht sie unprüfbar.","prueffrage":"Womit begründet Jonas, dass du seine Belege nicht sehen kannst?","rueckmeldung":[{"option":1,"text":"Jonas wertet dich tatsächlich ab, und das ist unfair. Eine bloße Abwertung macht ein Argument aber noch nicht unwiderlegbar. Der Kniff ist, dass er deinen Standpunkt einem Bewusstseinszustand zuschreibt, den jede Kritik bestätigt."},{"option":2,"text":"„Aufgewacht“ und „schlafen“ sind tatsächlich unscharf. Selbst mit klaren Definitionen bliebe die Sperre aber bestehen: Einwände würden weiter dem Zustand des Kritikers zugeschrieben statt geprüft. Der Fehler liegt in dieser Zuschreibung."},{"option":3,"text":"Jonas behandelt seine Belege faktisch wie unangreifbar. Er behauptet aber nicht, sie seien bewiesen, sondern dass du sie wegen deines „Schlafs“ nicht sehen kannst. Damit verlagert er den Streit vom Prüfen der Belege auf deinen angeblichen Zustand."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3b5c116310d409ab"}},{"id":"qx-g-004","clusterId":"G","werkstueckRef":"G.1.1","stufe":4,"question":"Welcher Denkfehler steckt in diesem Satz der Führungskraft, obwohl kein Schimpfwort fällt?","scenario":"In einer Firma sagt eine Führungskraft nach der Einführung eines neuen Konzepts: „Wer die Vorteile nicht sieht, ist einfach noch nicht so weit. Das erkennt man erst, wenn man den Sprung gewagt hat.“","options":["Die Kritiker werden persönlich abgewertet, statt dass ihre Einwände widerlegt werden, sodass ihre Kritik wegen ihrer Person nichts gilt.","Die Vorteile werden mit dem Sprung begründet und der Sprung mit den Vorteilen, sodass sich die Behauptung im Kreis selbst stützt.","Ein Meinungsunterschied wird zu einem Unterschied im Entwicklungsstand der Person erklärt, sodass Kritik von außen per Definition nichts zählt.","Die Belegschaft wird in zwei Lager geteilt, die schon so weit sind und die noch nicht, sodass für eine dritte, abwägende Haltung kein Platz mehr bleibt."],"correctIndex":2,"explanation":"Die Aussage dichtet sich gegen Prüfung ab: Nicht eine unterschiedliche Bewertung der Belege trennt die Lager, sondern ein angeblich anderer Zustand, den man erst nach dem „Sprung“ erreicht. Damit lässt sich jede Kritik abtun („noch nicht so weit“), und kein denkbarer Einwand könnte die Behauptung je widerlegen. Sie ist dann nicht mehr falsifizierbar. Dasselbe Muster steckt in Erweckungs-Rhetorik wie „Aufwachen“ und „Schlafschaf“, nur ohne Schimpfwort. Ob die Vorteile real sind, lässt sich prüfen: mit Belegen, die auch ein Skeptiker nachvollziehen kann, vor dem Sprung statt danach.","coreRule":"⚡ Wo Kritik nur noch „nicht so weit“ sein kann, ist eine Behauptung gegen Prüfung abgedichtet.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 3: Epistemologische Immunisierung; Falsifizierbarkeit)","status":"entwurf","kurz":"Der Satz erklärt Kritik zum Zeichen eines „noch nicht erreichten“ Zustands, den man nur durch den „Sprung“ verlässt. So kann kein Einwand die Behauptung mehr treffen. Der Denkfehler: Nicht die Belege trennen die Lager, sondern ein angeblicher Reifegrad.","prueffrage":"Welche Vorteile des Konzepts nennt die Führungskraft konkret, und woran ließen sie sich schon vor dem „Sprung“ prüfen?","rueckmeldung":[{"option":0,"text":"Abwertend klingt der Satz tatsächlich, denn Kritiker gelten als „noch nicht so weit“. Entscheidender ist aber, dass kein Einwand mehr zählen kann, weil jeder auf einen angeblichen Zustand zurückgeführt wird, nicht auf die Sache."},{"option":1,"text":"Ein Kreis wäre es, wenn die Vorteile durch den Sprung begründet würden. Der Satz sagt aber nur, dass man sie erst danach erkennt, und genau damit entzieht er sich der Prüfung, statt sich im Kreis zu stützen."},{"option":3,"text":"Die Teilung in „schon so weit“ und „noch nicht so weit“ ist im Satz tatsächlich angelegt. Das Kernproblem liegt aber woanders: Auch wer abwägt, gälte als „noch nicht so weit“, die Behauptung bleibt also gegen jeden Einwand abgedichtet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"cf1ac952bb63b244"}},{"id":"qx-g-005","clusterId":"G","werkstueckRef":"G.1.2","stufe":1,"question":"Ein Freund sagt: „Ich vertraue keinen Experten, ich recherchiere lieber selbst. Dazu gehört auch, dass ich mir das, was Fachleute dazu sagen, gar nicht erst anschaue.“ Wo liegt der Kern des Problems an dieser Haltung?","options":["Die Ablehnung der Experten klingt nach Unabhängigkeit, ist hier aber bloßes Misstrauen: Er lehnt Fachleute ab, ohne dafür eigene Gründe zu nennen.","Das Selbstrecherchieren klingt nach einer Tugend, wird hier aber so benutzt, dass es die Aussagen der Fachleute und alle Gegenargumente abwehrt.","Die Ablehnung der Experten klingt nach Unabhängigkeit, führt hier aber zur Selbstüberschätzung: Man hält sich ohne Fachwissen für ebenso kundig.","Das Recherchieren auf eigene Faust klingt nach Fleiß, ist hier aber kaum zu leisten: Er müsste sich dafür in viele Fachgebiete selbst einarbeiten."],"correctIndex":1,"explanation":"„Selbst nachdenken“ und „Quellen kritisch prüfen“ sind echte Tugenden und gehören zum Kern des wissenschaftlichen Skeptizismus. Der Satz des Freundes benutzt sie aber als Schutzmauer gegen Expertenwissen und als Freibrief, den wissenschaftlichen Konsens zu ignorieren, und das ist das Gegenteil von kritischem Prüfen. Dazu kommt ein falsches Dilemma („Experten glauben oder selbst denken“): Die dritte Möglichkeit ist, die Glaubwürdigkeit von Experten und Quellen selbst kritisch zu bewerten. Auch der Befund einer US-Panelbefragung aus der Pandemie passt dazu: Wer stärker zustimmte, eigene Recherche sei so viel wert wie das Wissen von Fachleuten, vertraute der Wissenschaft binnen drei Monaten weniger und hielt mehr Falsches über COVID-19 für wahr. Der Zusammenhang war allerdings schwach und stammt aus Befragungsdaten, nicht aus einem Experiment. Die Autoren lesen die Zustimmung zum Slogan eher als Ausdruck einer Haltung gegen Experten denn als Ausdruck sorgfältiger Prüfung, und sie raten vom Selbstrecherchieren nicht ab. Das Problem liegt in der Art, wie es hier eingesetzt wird.","coreRule":"⚡ Je edler ein Slogan klingt, desto genauer lohnt der Blick, was damit in der Praxis gemeint ist: Prüfen heißt auch, die stärksten Gegenargumente zu suchen, nicht sie auszublenden.","beleg":"Werkstück G.1.2 (Die linguistische Autopsie; Die rhetorische Funktion)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Selbst recherchieren ist eine Tugend, hier aber dient es als Schutzmauer: Wer Aussagen von Fachleuten gar nicht erst ansieht, prüft nicht kritisch, sondern wehrt Gegenargumente ab. Das Dilemma „Experten glauben oder selbst denken“ übersieht, dass man Quellen auch prüfen kann.","prueffrage":"Welche Quellen schaut sich dein Freund an, und welche schließt er schon vorab aus?","rueckmeldung":[{"option":0,"text":"Er nennt tatsächlich keine Gründe, doch das ist nicht der Kern. Entscheidend ist, dass er die Aussagen der Fachleute gar nicht erst ansieht und damit jede Prüfung und jedes Gegenargument von vornherein ausschließt."},{"option":2,"text":"Der Freund sagt nirgends, er wisse so viel wie Fachleute. Eine solche Selbstüberschätzung wäre in diesem Satz eine Unterstellung, die der Text nicht hergibt. Das Problem liegt darin, wie er seine Recherche nutzt: als Mauer gegen Gegenargumente."},{"option":3,"text":"Den Aufwand, sich in viele Fachgebiete einzuarbeiten, gibt es wirklich. Das Problem der Haltung ist er aber nicht: Man kann auch Experten und Quellen kritisch bewerten, statt alles selbst zu erarbeiten. Selbst zu recherchieren ist sogar eine Tugend."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"61e8390066ab2203"}},{"id":"qx-g-006","clusterId":"G","werkstueckRef":"G.1.2","stufe":2,"question":"Wie gehst du in diesem Gespräch am besten vor?","scenario":"Eine Kollegin sagt: „Zum Thema Impfen mache ich lieber meine eigene Recherche.“ Du möchtest sie nicht abwerten, aber auch nicht so tun, als sei jede Recherche gleich gut.","options":["Du verweist auf die Ausbildung der Impfärzte und rätst der Kollegin, deren Einschätzung zu folgen, weil Erfahrung mehr zählt als Eigenrecherche.","Du stimmst ihr zu und fragst, wie sie beim Impfthema recherchiert, weil gutes Selbstdenken einschließt, auch die eigene Vorgehensweise kritisch zu prüfen.","Du erzählst von einem Bekannten, dessen Eigenrecherche zum Impfen in die Irre führte, weil ein konkretes Beispiel mehr überzeugt als jedes Argument.","Du fragst, was sie zur Recherche über das Impfen bewegt, und hörst nur zu, weil Verständnis für ihre Sorgen wichtiger ist, als ihre Vorgehensweise zu prüfen."],"correctIndex":1,"explanation":"„Selbst nachdenken“ ist ein guter Grundsatz, der aber oft zweckentfremdet wird: als Freibrief, Fachwissen pauschal abzutun. Wer den Appell ablehnt, lässt sich auf ein falsches Dilemma ein („Experten glauben oder selbst denken“) und wirkt abwertend, was Abwehr erzeugt. Die tragfähige dritte Möglichkeit: Selbst denken und dabei die Glaubwürdigkeit von Quellen und Fachleuten kritisch bewerten. Dazu gehört, die eigene Methode zu hinterfragen: Suche ich auch nach den stärksten Gegenargumenten oder nur nach Bestätigung? Das lässt sich als echtes Interesse erfragen, ohne zu belehren. Der Hinweis auf die Ausbildung der Ärzte ist nicht falsch, ersetzt aber die Frage nach der Methode durch ein Autoritätsargument und wirkt belehrend. Ein Bekannter als Gegenbeispiel bleibt ein Einzelfall und überzeugt eher rhetorisch. Bloßes Zuhören schafft Vertrauen, lässt aber das zweite Ziel offen, nämlich nicht so zu tun, als sei jede Recherche gleich gut. Einordnung: In einer US-Befragung hing Zustimmung zum Slogan „eigene Recherche“ schwach mit mehr Fehlwissen und weniger Vertrauen in die Wissenschaft zusammen. Die Autoren deuten die Zustimmung eher als Ausdruck einer Haltung gegen Experten, nicht als Beleg dafür, dass Selbstrecherche selbst schadet.","coreRule":"⚡ Nimm den Appell zum Selbstdenken ernst und frag nach der Methode.","quote":"Wie stellst du bei deiner ‚eigenen Recherche‘ sicher, dass du nicht einfach nur deinem Bestätigungsfehler erliegst?","quoteLabel":"Eine mögliche Nachfrage:","beleg":"Werkstück G.1.2 (Das Anti-Denkmuster; Aktivierungs-Frage; Falsches Dilemma)","status":"entwurf","kurz":"Mit der Frage, wie sie recherchiert, nimmst du ihren Grundsatz ernst und prüfst zugleich die Methode, etwa ob sie auch nach den stärksten Gegenargumenten sucht. Wer stattdessen ablehnt, tappt ins falsche Dilemma „Experten glauben oder selbst denken“.","prueffrage":"Wie reagiert jemand vermutlich, dessen Vorhaben gleich zu Beginn als falsch oder unzuverlässig hingestellt wird?","rueckmeldung":[{"option":0,"text":"Die Ausbildung der Ärzte ist durchaus ein Grund für Vertrauen. Als Antwort ersetzt der Verweis aber die Frage nach der Methode durch ein Autoritätsargument, wirkt belehrend und kann Abwehr erzeugen."},{"option":2,"text":"Ein anschauliches Beispiel erregt Aufmerksamkeit. Ein einzelner Bekannter bleibt jedoch ein Einzelfall, überzeugt eher rhetorisch als sachlich und wirkt schnell wie eine Warnung von oben."},{"option":3,"text":"Zuhören schafft Vertrauen und nimmt Sorgen ernst. Ohne den Blick auf ihre Vorgehensweise bleibt aber offen, dass nicht jede Recherche gleich gut ist, und genau dieses zweite Ziel wird verfehlt."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"19955b9263b4da14"}},{"id":"qx-g-007","clusterId":"G","werkstueckRef":"G.1.2","stufe":3,"question":"Wie sicher darfst du aus diesem Befund auf Ursache und Wirkung schließen?","options":["Aus dem Befund folgt keine Ursache: Der Zusammenhang ist schwach, stammt aus Umfragedaten, und eine Haltung gegen Experten kann beide Seiten erklären.","Aus dem Befund folgt eine Ursache, aber nur für US-Erwachsene: Weil nur dort befragt wurde, lässt sich der Schluss nicht auf andere Länder übertragen.","Aus dem Befund folgt eine Ursache: Weil zweimal befragt wurde (Dezember 2020, März 2021), belegt die zeitliche Reihenfolge, was Ursache und was Wirkung ist.","Aus dem Befund folgt eine Aussage über jeden Einzelnen: Weil der Zusammenhang in der Gruppe besteht, gilt er für jede Person, die dem Slogan zustimmt."],"correctIndex":0,"explanation":"Der Zusammenhang ist schwach: Die Zustimmung zum Slogan erklärt statistisch rund ein Prozent der Unterschiede, der weit größte Teil bleibt offen. Es sind Befragungsdaten, kein Experiment; Ursache und Wirkung lassen sich daraus nicht ablesen. Plausibler ist eine dritte Erklärung: Wer Experten ohnehin misstraut, stimmt dem Slogan eher zu, vertraut der Wissenschaft weniger und glaubt eher Falsches. Genau so deuten die Studienautoren (Chinn und Hasell, 2023) den Befund: Die Zustimmung zum Slogan sei eher Ausdruck einer Haltung gegen Experten. Vom Selbstrecherchieren raten sie nicht ab, sie nennen es „both a prudent and flawed endeavor“.","coreRule":"⚡ Ein schwacher Zusammenhang in Umfragedaten ist ein Hinweis, kein Beweis für Ursache und Wirkung.","beleg":"Werkstück G.1.2 (Epistemologische Immunisierung); Fn. gl-g-dyor (Chinn/Hasell 2023, S. 1–3 und 6)","status":"entwurf","scenario":"Eine Schlagzeile meldet: „Studie zeigt: Wer ‚eigene Recherche‘ für genauso wertvoll hält wie das Wissen von Fachleuten, glaubt mehr Falsches über COVID-19 und vertraut der Wissenschaft weniger.“ Der Befund stammt aus einer Panelbefragung von US-Erwachsenen (Dezember 2020 und März 2021). Der Zusammenhang war schwach: Die Zustimmung zum Slogan erklärte nur rund 1 Prozent der Unterschiede bei den falschen Annahmen.","kurz":"Befragungsdaten zeigen hier nur einen schwachen Zusammenhang, keinen Beleg für eine Ursache. Der naheliegende Fehler ist, aus „tritt zusammen auf“ eine Wirkung zu machen, obwohl eine Haltung gegen Experten beides erklären kann.","prueffrage":"Wie groß ist der Anteil der Unterschiede, den die Zustimmung zum Slogan statistisch erklärt, und was bleibt übrig?","rueckmeldung":[{"option":1,"text":"Dass nur in den USA befragt wurde, ist eine echte Grenze, und ob der Befund anderswo gilt, bleibt offen. Der Schluss auf eine Ursache scheitert aber schon in der befragten Gruppe selbst: Aus Umfragedaten folgt sie nicht."},{"option":2,"text":"Zwei Befragungen wirken, als zeigten sie einen Verlauf. Die Reihenfolge allein sagt aber nicht, was wirkt: Auch eine dritte Größe wie das Misstrauen gegenüber Experten kann spätere Antworten mitbestimmen."},{"option":3,"text":"Ein Zusammenhang in der Gruppe lässt sich leicht auf jeden Einzelnen übertragen. Er sagt aber nur etwas über Durchschnitte, und bei rund einem Prozent erklärter Unterschiede sagt er über die einzelne Person kaum etwas."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6ceec3af4c3fbf9b"}},{"id":"qx-g-008","clusterId":"G","werkstueckRef":"G.1.2","stufe":4,"question":"Was ist an dieser Abwehr denkerisch fehlerhaft?","scenario":"Du legst einer Kollegin den Befund einer Virologin vor. Sie winkt ab: „Das sagen nur die Eliten, ich denke lieber selbst nach.“ Auf die Frage, was sie am Befund konkret falsch findet, geht sie nicht ein.","options":["Sie verwirft den Befund wegen der Gruppe seiner Urheber („Eliten“) statt wegen seiner Argumente und macht sich so gegen Kritik von Fachleuten unangreifbar.","Sie weicht der Sache aus, denn sie nennt auf Nachfrage keinen konkreten Fehler am Befund, und wer nichts benennen kann, sollte sich mit einem Urteil zurückhalten.","Sie bleibt zu ungenau, denn mit „Eliten“ sagt sie nicht, wen sie meint, und müsste erst klären, welche Gruppe gemeint ist, bevor man ihren Einwand prüfen kann.","Sie baut ein falsches Entweder-oder auf, denn sie tut so, als müsse man sich zwischen dem Befund von Fachleuten und dem eigenen Nachdenken entscheiden."],"correctIndex":0,"explanation":"Hier liegt ein Ad Hominem vor: Der Befund wird nicht an seinen Argumenten oder Methoden gemessen, sondern pauschal abgelehnt, weil die Urheber zur Gruppe der „Eliten“ zählen. Der Satz wirkt zugleich als Schutzmauer: Jede Kritik von Fachleuten lässt sich mit ihm abwehren, ganz gleich, wie gut sie begründet ist. Das ist ein Freibrief, den wissenschaftlichen Konsens zu ignorieren. Echtes Selbst-Nachdenken heißt dagegen, die eigenen Methoden zu hinterfragen und aktiv die stärksten Gegenargumente zu suchen. Dazu passt eine US-Panelbefragung aus der Pandemie (Chinn und Hasell, 2023): Je stärker Befragte zustimmten, „eigene Recherche“ sei so viel wert wie das Wissen von Fachleuten, desto eher sank binnen drei Monaten ihr Vertrauen in die Wissenschaft und desto mehr Falsches hielten sie über COVID-19 für wahr. Der Zusammenhang war schwach und stammt aus Befragungsdaten, nicht aus einem Experiment.","coreRule":"⚡ Wer die Quelle verwirft statt das Argument, prüft nicht, sondern immunisiert sich.","beleg":"Werkstück G.1.2 (Die rhetorische Funktion, Punkt 2: Epistemologische Immunisierung; Die transportierten Denkfehler: Ad Hominem)","status":"entwurf","kurz":"Der Befund wird nicht an seinen Argumenten geprüft, sondern allein wegen der Herkunft („Eliten“) verworfen. So lässt sich jede Kritik von Fachleuten abwehren, egal wie gut sie begründet ist. Eigenes Denken hieße dagegen, Methoden und stärkste Gegenargumente zu prüfen.","prueffrage":"Welchen einzelnen Punkt des Befunds hat die Kollegin bisher angesprochen?","rueckmeldung":[{"option":1,"text":"Dass sie auf Nachfrage keinen konkreten Fehler nennt, stimmt und ist auffällig. Es ist aber nur ein Anzeichen. Der Kern liegt tiefer: Sie verwirft den Befund wegen seiner Urheber statt wegen seiner Argumente."},{"option":2,"text":"„Eliten“ ist tatsächlich unscharf. Selbst mit klarer Gruppenangabe bliebe der Fehler aber bestehen: Der Befund würde weiter wegen der Herkunft der Urheber abgelehnt, nicht wegen seiner Argumente."},{"option":3,"text":"Selbst denken und Fachleuten folgen schließen sich nicht aus, daran kann man sich stören. Entscheidender ist aber, dass sie den Befund pauschal wegen seiner Urheber verwirft, statt seine Argumente zu prüfen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d2044aeab3c8835e"}},{"id":"qx-g-009","clusterId":"G","werkstueckRef":"G.1.3","stufe":1,"question":"Wie würdest du die Aussage dieser Person am treffendsten einordnen?","options":["Sie stellt eine plötzliche Erweckung als Befreiung dar und teilt die Welt in Wissende und Schlafende, ohne Belege zu nennen.","Sie übt zugespitzte Medienkritik, denn die rote Pille steht hier bildhaft für einen wacheren, kritischeren Blick auf Nachrichten.","Sie schildert eine persönliche Erfahrung, die als eigenes Erlebnis gilt und sich von außen kaum prüfen oder bestreiten lässt.","Sie benutzt das Bild der roten Pille als Beweis, denn schon das Bild soll zeigen, dass ihre Sicht auf die Medien zutrifft."],"correctIndex":0,"explanation":"Die Metapher stammt aus dem Film „The Matrix“: Die rote Pille lässt Neo aus der Simulation erwachen. Als Erzählmuster macht sie aus einer Meinungsänderung einen plötzlichen Moment der Erweckung und teilt die Menschen in „Aufgewachte“ und „Schlafschafe“. Genau das passiert hier: Statt Belege zu nennen, beruft sich die Person auf ihr Erweckungserlebnis. Dem plötzlichen „Red Pill“-Moment steht der langsame, schrittweise Prozess gegenüber, in dem man Belege prüft und neu bewertet. Dass der Begriff nur in extremistischen Gruppen vorkäme, stimmt nicht: Er wird auch in Verschwörungsmythen und als allgemeiner Internet-Slang für jede Erkenntnis gegen den Mainstream gebraucht. Und die Option, sich der wissenschaftlichen Mehrheitsmeinung anzuschließen, passt nicht, weil die Metapher gerade für alternative Weltanschauungen steht, die sich gegen den Mainstream richten.","coreRule":"⚡ „Rote Pille“ erzählt Bekehrung als Erweckung. Wissen entsteht aber durch Prüfen, nicht durch einen einzigen Moment.","beleg":"Werkstück G.1.3 (Die Wahl; Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"In einem Forum schreibt jemand: „Ich habe die rote Pille genommen. Seitdem sehe ich, wie die Medien uns alle belügen. Wer mir nicht glaubt, schläft noch.“","kurz":"Hier wird eine Meinungsänderung zum plötzlichen Erweckungsmoment erklärt und die Welt in Wissende und Schlafende geteilt, statt Belege zu nennen. Wer dem Bild folgt, übersieht, dass die Aussage selbst nichts belegt.","prueffrage":"Welche überprüfbare Angabe macht die Person, außer dass sie jetzt „sieht“, was andere nicht sehen?","rueckmeldung":[{"option":1,"text":"Kritik an Medien kann berechtigt sein, und die Pille ist ein Bild. Hier wird aber kein genauerer Blick verlangt, sondern behauptet, alle würden belogen, und wer zweifelt, gilt als Schlafender. Das ist Abwertung, keine Kritik."},{"option":2,"text":"Das Erleben selbst kann man der Person nicht absprechen. Sie schließt daraus aber auf eine Tatsache, nämlich dass die Medien alle belügen, und die lässt sich sehr wohl prüfen. Das Erlebnis ersetzt hier die Belege."},{"option":3,"text":"Richtig ist, dass keine Belege genannt werden. Das Bild beweist aber nichts, es ist ein Erzählmuster, das Zweifler als Schlafende einordnet. Die Aussage bringt also kein Argument über das Bild vor, sondern verzichtet auf eines."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18, 24","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5ab3260a052abf29"}},{"id":"qx-g-010","clusterId":"G","werkstueckRef":"G.1.3","stufe":2,"question":"Welche Antwort hilft dir am besten, die Behauptung deines Freundes zu prüfen, statt sie nur anzunehmen oder abzuwehren?","scenario":"Ein Freund schreibt dir: „Du musst die rote Pille nehmen und die Wahrheit über X erkennen! Die offiziellen Stellen wollen nicht, dass du das weißt.“ Er beschreibt seine eigene Erkenntnis als plötzlichen „Aha-Moment“, nach dem für ihn alles klar war.","options":["„Erzähl mir von deinem Aha-Moment: Was hat sich danach für dich verändert, und seit wann siehst du das so?“","„Wie viele Leute sehen die Wahrheit über X inzwischen genauso wie du, oder bist du damit noch ziemlich allein?“","„Warum sollten die offiziellen Stellen das überhaupt verbergen wollen, und was hätten sie selbst davon?“","„Woher weißt du, dass deine Pille nicht von jemandem stammt, der dir eine bestimmte ‚Wahrheit‘ zeigen will?“"],"correctIndex":3,"explanation":"Die Behauptung ist so gebaut, dass es nur zwei Wege zu geben scheint: schlucken oder in der Täuschung bleiben. Das ist ein falsches Dilemma. Die beste Antwort sprengt dieses Schema, indem sie nach Quelle und Methode fragt: Wer hat die „Erkenntnis“ hergestellt, mit welchem Interesse, und wie wurde sie geprüft? So wird aus einem Befreiungsmoment eine prüfbare Behauptung. Wahre Befreiung liegt nicht im Schlucken einer Pille, sondern darin, die Inhaltsstoffe jeder Pille selbst analysieren zu können.","coreRule":"⚡ Dreh die Pille um: Entscheidend ist nicht ihre Farbe, sondern wer sie hergestellt hat und wie du sie prüfst.","beleg":"Werkstück G.1.3 (Werkbank-Frage; Verbindungen: Falsches Dilemma)","status":"entwurf","kurz":"Der Freund stellt nur zwei Wege hin: die Pille schlucken oder getäuscht bleiben. Dieses falsche Dilemma sprengst du, wenn du nach Quelle und Methode fragst: Wer hat die „Erkenntnis“ hergestellt, mit welchem Interesse, und wie wurde sie geprüft?","prueffrage":"Welche überprüfbaren Angaben zu X enthält die Nachricht deines Freundes außer dem Bild von der Pille?","rueckmeldung":[{"option":0,"text":"Zuhören hält das Gespräch offen und zeigt Interesse am Freund. Geprüft wird die Behauptung dadurch aber nicht: Du erfährst, wie sich der Aha-Moment angefühlt hat, nicht, woher die „Erkenntnis“ stammt und wie verlässlich sie ist."},{"option":1,"text":"Wie viele Menschen etwas glauben, sagt wenig darüber, ob es stimmt. Eine große Zahl kann irren, und eine kleine Zahl passt sogar zur Erzählung vom unterdrückten Wissen. Über Quelle und Prüfung erfährst du so nichts."},{"option":2,"text":"Nach dem Motiv der Stellen zu fragen, führt dich tief in die Erzählung des Freundes hinein, statt seine Erkenntnis zu prüfen. Ein ausgemaltes Motiv macht die Behauptung plausibler, belegt sie aber nicht. Zu fragen wäre, wer die „Erkenntnis“ hergestellt hat und wie sie geprüft wurde."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"463e86318d73bf17"}},{"id":"qx-g-011","clusterId":"G","werkstueckRef":"G.1.3","stufe":3,"question":"Eine Kollegin sagt im Gespräch: „Das war für mich echt eine rote Pille.“ Im Netz behauptet jemand: „Wer die blaue Pille schluckt, will die Wahrheit nicht sehen – deshalb ist jede Studie, die mir widerspricht, Teil der Matrix.“ Woran erkennst du, dass die Metapher im zweiten Fall zum Problem wird?","options":["Daran, dass der Beitrag die Metapher zur einzigen Realität erklärt und dadurch jede Prüfung durch Belege, Studien und Gegenargumente im Voraus ablehnt.","Daran, dass jede Metapher vereinfacht: Ein Bild hebt einen Aspekt hervor und lässt andere weg, sodass es die Wirklichkeit nie vollständig abbildet.","Daran, dass das Bild Gefühle anspricht: Metaphern wirken oft stärker auf Empfindungen als auf Überlegungen, sodass sich sachliche Gründe schwerer durchsetzen.","Daran, dass das Bild aus einer Fiktion stammt: Ein Film zeigt eine erfundene Welt, und ein Vergleich damit trifft die Wirklichkeit höchstens ungefähr."],"correctIndex":0,"explanation":"Eine Metapher zu benutzen ist für sich genommen harmlos; auch die Kollegin nutzt dasselbe Bild, ohne dass etwas schiefläuft. Problematisch wird es, wenn das Bild zur einzigen Realität erklärt wird und damit jede Information, die widerspricht, schon im Voraus als Täuschung gilt. Dann ist die Aussage gegen Belege immunisiert, und Argumente können sie nicht mehr erreichen. Entscheidend ist also nicht das Bild selbst, sondern ob im Namen des Bildes auf jede Prüfung verzichtet wird. Dass Bilder vereinfachen, Gefühle ansprechen und aus einer Fiktion stammen, gilt zwar für jede Metapher, trifft aber auf die Kollegin genauso zu und erklärt deshalb nicht den Unterschied zwischen beiden Fällen.","coreRule":"⚡ Nicht die Metapher ist das Problem, sondern der Verzicht auf jede Prüfung im Namen der Metapher.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.3 (Der Kipppunkt)","status":"entwurf","scenario":"Zwei Aussagen im Vergleich: Die Kollegin beschreibt eine Erkenntnis mit einem Filmbild. Der Netzbeitrag verwendet dasselbe Bild, um jede widersprechende Quelle von vornherein auszuschließen.","kurz":"Das Bild selbst ist harmlos, auch die Kollegin nutzt es. Zum Problem wird es, wenn es zur einzigen Realität erklärt wird und jeder Widerspruch vorab als Täuschung gilt. Dann erreichen Belege die Aussage nicht mehr.","prueffrage":"Welche Folgen zieht die Kollegin aus ihrem Bild, und welche zieht der Netzbeitrag daraus?","rueckmeldung":[{"option":1,"text":"Dass ein Bild vereinfacht und Aspekte weglässt, stimmt für jede Metapher. Genau deshalb erklärt es den Unterschied nicht: Die Kollegin nutzt dasselbe Bild, ohne dass etwas schiefläuft."},{"option":2,"text":"Metaphern sprechen oft Gefühle an, doch das gilt für die Kollegin ebenso wie für den Netzbeitrag. Entscheidend ist, ob im Namen des Bildes auf jede Prüfung verzichtet wird, nicht wie stark es berührt."},{"option":3,"text":"Dass das Bild aus einem Film stammt, trifft auf beide Aussagen zu, und bei der Kollegin stört es niemanden. Der Unterschied liegt darin, ob widersprechende Quellen vorab ausgeschlossen werden."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"9716d9de415c218b"}},{"id":"qx-g-012","clusterId":"G","werkstueckRef":"G.1.4","stufe":1,"question":"Welche Frage prüft am besten, ob der Slogan „Mein Körper, meine Wahl“ in dieser Situation ein tragfähiges Argument ist?","options":["Betrifft die Entscheidung nur den eigenen Körper, oder setzt sie auch andere einem vorhersehbaren Risiko aus?","Hat die Wissenschaftlerin ein eigenes Interesse an einer Impfpflicht, das ihre Auswahl der Daten beeinflusst haben könnte?","Stammen die Daten zur Ansteckung aus einer einzelnen Studie oder aus mehreren voneinander unabhängigen Untersuchungen?","Lässt sich der Slogan so verschieden auslegen, dass kaum zu sagen ist, was er in diesem Zusammenhang überhaupt behauptet?"],"correctIndex":0,"explanation":"Ein Slogan trägt nur dann, wenn seine Voraussetzung auch im neuen Zusammenhang gilt. Der Satz „Mein Körper, meine Wahl“ ist stark, wo eine Entscheidung wirklich nur den eigenen Körper betrifft. Bei einer ansteckenden Krankheit trifft das nicht rein zu, weil die Entscheidung Folgen für andere hat (Ansteckungsrisiko), etwa für Menschen mit geschwächtem Immunsystem. Auch eine geliehene moralische Aura ersetzt keine Begründung, denn sie macht den Satz nicht passender für den neuen Fall. Der Kern der Prüfung ist deshalb, ob die Voraussetzung des Slogans hier erfüllt ist: Berührt die Wahl nur mich, oder auch andere? Die Frage nach Interessen und Datenlage ist bei Studien sinnvoll, prüft aber die Wissenschaftlerin und nicht den Slogan des Bürgers. Und eine Frage nach der Mehrdeutigkeit führt ins Leere, denn der Satz ist klar und eindeutig formuliert.","coreRule":"⚡ Geliehene Moral ersetzt kein Argument: Prüfe, ob die Voraussetzung des Slogans im neuen Zusammenhang erfüllt ist.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 1: Er kapert die moralische Hoheit)","status":"entwurf","scenario":"In einer Debatte über eine Impfpflicht während einer Pandemie legt eine Wissenschaftlerin Daten zur Ansteckung und zum Schutz Dritter vor. Ein Bürger antwortet nur: „Mein Körper, meine Wahl.“ Der Satz stammt ursprünglich aus dem Kampf um das Recht auf Entscheidungen über den eigenen Körper und hat dort hohe moralische Überzeugungskraft.","kurz":"Der Slogan trägt nur, wenn seine Voraussetzung auch hier gilt: dass die Entscheidung allein den eigenen Körper betrifft. Bei einer ansteckenden Krankheit trifft das nicht rein zu, und geliehene moralische Kraft ersetzt keine Begründung für den neuen Fall.","prueffrage":"Was zeigen die Daten der Wissenschaftlerin, und auf welchen ihrer Punkte geht der Bürger mit seinem Satz ein?","rueckmeldung":[{"option":1,"text":"Interessen hinter Daten zu hinterfragen ist bei Studien üblich und sinnvoll. Hier prüft die Frage aber die Wissenschaftlerin, während der Slogan des Bürgers unbeantwortet bleibt: Ob er in diesem Fall passt, klärt sie nicht."},{"option":2,"text":"Die Datenlage zu prüfen gehört zum guten Umgang mit Studien. Sie sagt jedoch nichts darüber, ob der Satz des Bürgers im neuen Zusammenhang trägt. Die Frage zielt auf die Daten der Wissenschaftlerin, nicht auf seinen Slogan."},{"option":3,"text":"Bei manchen Schlagworten ist Mehrdeutigkeit tatsächlich das Problem. Dieser Satz ist aber klar und eindeutig. Fraglich ist nicht, was er meint, sondern ob seine Voraussetzung in diesem Fall erfüllt ist."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ac7326123ec3dd13"}},{"id":"qx-g-013","clusterId":"G","werkstueckRef":"G.1.4","stufe":2,"question":"Welche Erwiderung hält das Gespräch am ehesten offen und führt zum eigentlichen Streitpunkt?","scenario":"Du fragst in einer Diskussion über Ansteckungsschutz: „Aber was ist mit den immungeschwächten Menschen, die du ansteckst?“ Dein Gegenüber antwortet nur: „Mein Körper, meine Wahl.“ Du willst das Gespräch weiterführen, statt dass es hier endet.","options":["Du legst Zahlen zu schweren Verläufen bei immungeschwächten Menschen vor und fragst, wie er dieses Risiko für andere einschätzt, damit er die Sorge sachlich bewertet.","Du hältst dagegen, dass seine Freiheit dort endet, wo sie anderen schadet, damit er erkennt, dass sein Slogan hier nicht als Begründung ausreicht.","Du weist darauf hin, dass der Slogan aus einem ganz anderen Streit stammt und hier nicht passt, damit er seine Wortwahl überdenkt und dein Anliegen aufgreift.","Du stimmst dem Recht zu und zeigst den Konflikt: Selbstbestimmung ist ein hohes Gut, steht hier aber gegen das Recht anderer auf körperliche Unversehrtheit."],"correctIndex":3,"explanation":"Am besten greifst du das Recht nicht an, sondern stimmst ihm zu und zeigst den Konflikt auf. Das Recht auf Selbstbestimmung gilt weiter, es hat aber Grenzen, wo es auf die Rechte anderer trifft. Der Slogan wirkt wie ein Schild, an dem jede Evidenz abprallt. Die Erwiderung, die zustimmt und den Konflikt zweier berechtigter Ansprüche benennt, erweitert den Rahmen. Aus einem Totschlagargument wird so eine Abwägung, über die man reden kann.","coreRule":"⚡ Greif das Recht nicht an: Stimm ihm zu und zeig, wo es auf ein anderes Recht trifft.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.4 (Das Anti-Denkmuster, Skript 1: Der Rechte-Konflikt; Red Flags)","status":"entwurf","kurz":"Wer dem Recht auf Selbstbestimmung zustimmt und ihm das Recht anderer auf Unversehrtheit gegenüberstellt, macht aus dem Totschlagargument eine Abwägung. Der naheliegende Fehler ist, den Slogan anzugreifen oder mit Fakten zu beschießen, statt das berechtigte Anliegen darin ernst zu nehmen.","prueffrage":"Welche Erwiderung würde dein Gegenüber vermutlich als Angriff auf sich selbst verstehen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Zahlen machen das Anliegen greifbar und wirken sachlich. Der Slogan ist aber eine Rechtsposition, kein Streit um Fakten, und Evidenz prallt daran ab. Die Frage bleibt im Faktischen und lässt den eigentlichen Streitpunkt unausgesprochen."},{"option":1,"text":"Dass Freiheit Grenzen hat, ist ein tragfähiger Gedanke. Als Gegenangriff formuliert, wirkt er jedoch wie eine Belehrung und stellt sein Recht infrage, statt es anzuerkennen. So gerät er in die Defensive, und das Gespräch endet eher, als dass es weitergeht."},{"option":2,"text":"Die Wortwahl zu kritisieren, rückt den Satz in den Mittelpunkt und lässt die Sache liegen. Ob der Slogan hier passt, ist zudem nicht der Streitpunkt; wer so antwortet, wirkt besserwisserisch und holt ihn nicht dort ab, wo sein berechtigtes Anliegen liegt."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"994abc9772731ade"}},{"id":"qx-g-014","clusterId":"G","werkstueckRef":"G.1.4","stufe":3,"question":"Sophie sagt in einer Diskussion über eine Impfung während einer Pandemie: „Ob ich mich impfen lasse, ist meine Privatsache, so wie die Entscheidung für ein Tattoo.“ Was ist an dieser Gleichsetzung der Fehler?","options":["Sophie übersieht, dass eine Impfentscheidung das Ansteckungsrisiko anderer verändern und, wenn viele gleich entscheiden, das Gesundheitssystem überlasten kann.","Sophie übersieht, dass eine Impfung anders als ein Tattoo ein medizinischer Eingriff mit möglichen Nebenwirkungen ist und deshalb gründlicher abgewogen werden muss.","Sophie übersieht, dass ein Tattoo eine dauerhaft sichtbare Veränderung ist, eine Impfung aber ein kurzer Eingriff, sodass sich beides kaum vergleichen lässt.","Sophie übersieht, dass über eine Impfung anders als über ein Tattoo nicht der persönliche Geschmack entscheiden sollte, sondern der Rat von Fachleuten."],"correctIndex":0,"explanation":"Eine Tätowierung ist eine rein private Wahl. Eine Impfentscheidung in einer Pandemie kann dagegen das Ansteckungsrisiko anderer verändern, vor allem für immungeschwächte Menschen, je nachdem, wie gut der Impfstoff auch vor Übertragung schützt. Fachlich spricht man hier von einer „Externalität“. Dazu kommt eine Konsequenz zweiter Ordnung: Treffen viele Menschen dieselbe Entscheidung, kann das Gesundheitssystem überlastet werden. Das Recht auf körperliche Selbstbestimmung bleibt davon unberührt. Wer etwa eine empfohlene Operation ablehnt, entscheidet legitim, weil es dabei um den Schutz des eigenen Körpers vor einem Eingriff geht. Der Fehler in Sophies Aussage liegt also nicht darin, dieses Recht zu betonen, sondern darin, eine Handlung mit Folgen für Dritte wie eine rein private Handlung zu behandeln.","coreRule":"⚡ Eine Wahl mit Folgen für Dritte ist keine rein private Wahl mehr.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 3; Der Kipppunkt; Anti-Denkmuster, Skript 2)","status":"entwurf","scenario":"","kurz":"Eine Impfung in einer Pandemie kann das Ansteckungsrisiko anderer verändern, ein Tattoo betrifft nur die Person selbst. Der Fehler ist, eine Handlung mit Folgen für Dritte wie eine rein private zu behandeln; Selbstbestimmung bleibt davon unberührt.","prueffrage":"Darf man eine ärztlich empfohlene Operation ablehnen, und was unterscheidet diese Entscheidung von Sophies Impfentscheidung?","rueckmeldung":[{"option":1,"text":"Dass eine Impfung ein Eingriff mit möglichen Nebenwirkungen ist, stimmt, und eine Abwägung ist sinnvoll. Mit der Gleichsetzung hat das aber wenig zu tun: Auch ein Tattoo birgt Risiken. Der Unterschied liegt in den Folgen für andere."},{"option":2,"text":"Dauer und Sichtbarkeit unterscheiden Tattoo und Impfung tatsächlich. Beide Eigenschaften betreffen aber nur die Handlung selbst. Entscheidend ist, ob andere von der Entscheidung berührt werden, und dort liegt der eigentliche Unterschied."},{"option":3,"text":"Fachlicher Rat ist bei medizinischen Fragen oft wertvoll. Aber auch gegen einen ärztlichen Rat kann man legitim über den eigenen Körper entscheiden. Der Haken an Sophies Satz liegt woanders: Sie blendet aus, dass andere von der Entscheidung betroffen sind."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"958601be53408122"}},{"id":"qx-g-015","clusterId":"G","werkstueckRef":"G.1.4","stufe":4,"question":"Was trägt an dieser Berufung auf Selbstbestimmung nicht?","scenario":"Eltern sagen: „Es ist meine Entscheidung, meinem Kind bei Krebs nur Globuli zu geben. Das ist meine Selbstbestimmung.“","options":["Es geht nicht um eine Methode unter vielen, sondern um ein unwirksames Mittel; Selbstbestimmung deckt nur die Wahl zwischen Behandlungen, die auch wirken.","Es geht nicht um irgendeine Wahl, sondern um eine, die Aufklärung braucht; Selbstbestimmung trägt erst, wenn die Eltern über die Folgen ärztlich aufgeklärt sind.","Es geht nicht um den eigenen Körper, sondern um den eines anderen Menschen; hier stößt das Recht der Eltern an die Fürsorgepflicht für das Kind.","Es geht nicht um eine Kleinigkeit, sondern um Krebs; bei so ernsten Krankheiten tritt die Selbstbestimmung hinter das ärztliche Urteil zurück."],"correctIndex":2,"explanation":"Körperliche Selbstbestimmung schützt Menschen davor, dass andere über ihren Körper verfügen. Sie gilt für den eigenen Körper. Hier entscheiden die Eltern aber über die Behandlung eines anderen Menschen, und zwar für eine wirkungslose Therapie. Dabei kollidiert das Recht des Individuums mit der Fürsorgepflicht für andere. Ein Recht als absolut hinzustellen, ohne seine Grenzen und die Rechte anderer anzuerkennen, ist ein Anzeichen für rhetorischen Missbrauch der Selbstbestimmung.","coreRule":"⚡ Selbstbestimmung gilt für den eigenen Körper; bei Entscheidungen für andere tritt die Fürsorgepflicht hinzu.","beleg":"Werkstück G.1.4 (Anwendung & Relevanz: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Selbstbestimmung schützt vor Verfügung über den eigenen Körper. Die Eltern entscheiden hier aber über den Körper ihres Kindes, und dann stößt ihr Recht an die Fürsorgepflicht. Wer ein Recht als grenzenlos hinstellt, missbraucht es rhetorisch.","prueffrage":"Was geschieht vermutlich mit der Krebserkrankung, wenn sie nur mit Globuli behandelt wird?","rueckmeldung":[{"option":0,"text":"Dass Globuli bei Krebs nicht wirken, ist richtig und macht die Lage ernst. Der Einwand gegen die Berufung liegt aber woanders: Auch bei einem unwirksamen Mittel wäre es für den eigenen Körper eine Frage der Selbstbestimmung. Entscheidend ist, wer da entscheidet und für wen."},{"option":1,"text":"Gute ärztliche Aufklärung gehört tatsächlich zu medizinischen Entscheidungen. Sie löst das Problem aber nicht: Auch gut informierte Eltern entscheiden hier über den Körper eines anderen Menschen. Mehr Wissen ändert nichts daran, wessen Körper betroffen ist."},{"option":3,"text":"Die Schwere der Krankheit macht die Entscheidung folgenreich. Erwachsene dürfen aber auch bei schweren Krankheiten über ihre eigene Behandlung bestimmen, ein pauschaler Vorrang des ärztlichen Urteils besteht nicht. Das Problem liegt darin, dass es um das Kind geht."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Grundgesetz Art. 6 Abs. 2 (Elternrecht und -pflicht, Wächteramt des Staates)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_6.html","abruf":"2026-10-12"},{"typ":"url","kurz":"BGB § 1666 Abs. 1 (Gefährdung des Kindeswohls)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/bgb/__1666.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4de304f35072c8cd"}},{"id":"qx-g-016","clusterId":"G","werkstueckRef":"G.2.1","stufe":1,"question":"In einer Diskussion sagt jemand: „Dass die Wirtschaft so schlecht läuft, liegt an den Eliten. Die steuern im Hintergrund alles, Politik, Konzerne und Medien. Wenn ein Politiker sich als unschuldig erweist, war er eben nur eine Marionette der wahren Elite.“ Was ist an dieser Argumentation das Kernproblem?","options":["Die Behauptung lässt sich nicht widerlegen: Die „Eliten“ bleiben undefiniert, und entlastete Politiker gelten einfach als Marionetten der wahren Elite.","Die Behauptung ist zu einfach: Sie führt die schlechte Wirtschaftslage auf eine einzige Ursache zurück, obwohl dabei viele verschiedene Gründe zusammenwirken.","Die Behauptung pauschalisiert: Sie wirft Politik, Konzerne und Medien in einen Topf, obwohl dort Menschen mit sehr verschiedenen Interessen handeln.","Die Behauptung ist im Kern vertretbar: Einflussreiche Gruppen prägen Politik, Konzerne und Medien, nur ist die Rede vom Steuern im Hintergrund übertrieben."],"correctIndex":0,"explanation":"Das Argument ist durch Vagheit gegen Widerlegung abgeschirmt: Da nie genau definiert wird, wer „die Eliten“ sind, kann die Behauptung nie widerlegt werden. Erweist sich ein Beschuldigter als unschuldig, war er eben nur eine Marionette der „wahren Elite“ dahinter. Der Feind ist wie ein Nebel, man kann ihn nicht festnageln. Wer eine solche Behauptung ernsthaft prüfen will, braucht deshalb Präzision: konkrete Namen und überprüfbare Belege dafür, dass sich diese Personen abgesprochen haben. Außerdem wird aus Menschen in Machtpositionen eine einzige, geheime und bösartige Kabale gemacht.","coreRule":"⚡ Wer „die Eliten“ sagt, ohne Namen und Belege zu nennen, baut eine Behauptung, die sich nicht widerlegen lässt. Frag deshalb nach konkreten Personen und überprüfbaren Absprachen.","beleg":"Werkstück G.2.1 (Die linguistische Autopsie)","status":"entwurf","scenario":"","kurz":"Die Behauptung ist durch Vagheit gegen Widerlegung geschützt: Wer „die Eliten“ sind, bleibt offen, und jeder Entlastete gilt als Marionette der „wahren“ Elite. Was sich nie widerlegen lässt, lässt sich auch nie belegen.","prueffrage":"Was bleibt von der Behauptung übrig, wenn sich ein beschuldigter Politiker als unschuldig erweist?","rueckmeldung":[{"option":1,"text":"Die Wirtschaftslage hat oft tatsächlich viele Gründe, und das macht eine einzelne Schuldzuweisung schon verdächtig. Das Kernproblem liegt aber tiefer: Das Argument lässt sich gar nicht prüfen, weil es jeden Gegenbeleg zur Bestätigung umdeutet."},{"option":2,"text":"Daran stimmt: Aus vielen Menschen in Machtpositionen wird hier eine einheitliche, verschworene Gruppe gemacht. Das ist aber eher eine Folge als der Kern. Entscheidend ist, dass die Aussage durch ihre Unschärfe nie widerlegt werden kann."},{"option":3,"text":"Dass einflussreiche Gruppen Entscheidungen prägen, ist als allgemeine Aussage plausibel. Behauptet wird hier aber etwas anderes: dass ein verdeckter Kreis alles steuert, und jeder Gegenbeweis gilt als Beleg dafür. So bleibt nichts Prüfbares übrig, das man vertreten könnte."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"651977fb03261bd0"}},{"id":"qx-g-017","clusterId":"G","werkstueckRef":"G.2.1","stufe":2,"question":"Was ist an dieser Behauptung das zentrale Problem, und welche Rückfrage prüft sie am besten?","scenario":"In einer Diskussion sagt jemand: „Die Eliten haben die Krise geplant.“ Auf Nachfrage, wer das sei, antwortet er: „Na, die da oben eben, die halten alle zusammen.“ Als einzelne Politiker oder Konzernchefs genannt werden, die nachweislich nichts abgesprochen haben, sagt er: „Die waren doch nur Marionetten der wahren Elite dahinter.“","options":["Die Behauptung ist ein Pauschalurteil über die Mächtigen als Ganze (Verallgemeinerung). Am besten fragst du, ob er Politiker und Konzernchefs wirklich ohne Unterschied für beteiligt hält.","Die Behauptung ist unwiderlegbar, weil „die Eliten“ nirgends festgelegt sind (Immunisierung). Am besten fragst du, wer konkret dazugehört und welcher prüfbare Beleg ihre Absprache zeigt.","Die Behauptung lässt offen, wozu die Krise geplant sein soll (fehlendes Motiv). Am besten fragst du, wer von der Krise profitiert hat, denn das zeigt, wer tatsächlich dahintersteckt.","Die Behauptung übergeht die genannten Gegenbeispiele (Bestätigungsfehler). Am besten fragst du nach weiteren Politikern und Konzernchefs und prüfst nacheinander, ob sie beteiligt waren."],"correctIndex":1,"explanation":"Der Begriff „die Eliten“ wird nie definiert, und jeder Gegenbeweis wird mit „Marionette der wahren Elite“ aufgefangen. Eine Behauptung, die durch keinen denkbaren Fall widerlegt werden kann, sagt nichts Überprüfbares über die Welt. Die Rückfrage nach konkreten Personen, einem konkreten Ziel und einem Beleg für die Absprache macht aus der Stimmung eine prüfbare Aussage. Sie bestreitet nicht, dass es einflussreiche Gruppen gibt oder dass Mächtige kritisiert werden dürfen. Sie zeigt nur, ob die Behauptung etwas Festes enthält, das man testen kann.","coreRule":"⚡ Wer „die Eliten“ sagt, soll Namen, Ziel und Beleg nennen können. Eine Behauptung, die jeden Gegenbeweis einbaut, ist unprüfbar.","quote":"Kannst du bitte präzise sein? Wer genau gehört zu diesen ‚Eliten‘? Nenne bitte fünf Namen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.2.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Ein Begriff, den niemand festlegt, plus ein Ausweg für jeden Gegenbeweis ergibt eine Behauptung, die gar nicht scheitern kann. Erst die Frage nach konkreten Personen, Ziel und Beleg macht daraus etwas Prüfbares.","prueffrage":"Was ändert sich an der Behauptung, nachdem Politiker genannt wurden, die nachweislich nichts abgesprochen haben?","rueckmeldung":[{"option":0,"text":"Dass „die Eliten“ sehr pauschal klingt, stimmt. Das Kernproblem liegt aber woanders: Auf „nicht alle“ folgt leicht „ich meine ja die wahre Elite“, und die Behauptung bleibt unangreifbar."},{"option":2,"text":"Nach Ziel und Nutzen zu fragen ist sinnvoll, doch Profit allein belegt keine Planung. Wer von einer Krise profitiert, muss sie nicht abgesprochen haben, und auch dieser Befund ließe sich wieder auf die „wahre Elite“ umdeuten."},{"option":3,"text":"Dass die Gegenbeispiele einfach umgedeutet werden, ist richtig beobachtet. Weitere Namen abzuarbeiten führt aber in dieselbe Schleife, denn jeder Fall würde wieder zur „Marionette“. Erst eine feste Definition und ein Beleg brechen das Muster."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f5acf06cfff363cf"}},{"id":"qx-g-018","clusterId":"G","werkstueckRef":"G.2.1","stufe":3,"question":"Wie solltest du den Beitrag und den Streit der beiden Leser am besten beurteilen?","scenario":"In einem Online-Beitrag wird mehrfach „Globalisten“ als Schuldiger für Wirtschaftskrise, Pandemie und Kriege genannt. Wer damit gemeint ist, bleibt offen, und Juden werden nirgends erwähnt. Eine Leserin schreibt darunter: „Das ist doch klar antisemitisch!“ Ein anderer Leser antwortet: „Das Wort ist völlig neutral, du unterstellst da etwas.“","options":["Das Wort gilt in solchen Zusammenhängen als bekannter antisemitischer Code. Ob es hier so gemeint ist, zeigt erst der Kontext: wer genau gemeint ist und welche Belege es gibt.","Das Wort ist ohne Nennung von Juden nur ein Wort. Da der Text niemanden ausdrücklich meint, darf man ihm keine antisemitische Aussage zuschreiben, solange der Verfasser sie nicht selbst bestätigt.","Das Wort gilt als bekannter antisemitischer Code. Wer mögliche Betroffene schützen will, behandelt den Beitrag deshalb als antisemitisch, bis der Verfasser das Gegenteil belegt.","Das Wort lässt sich nicht eindeutig deuten. Da niemand in den Verfasser hineinsehen kann, ist jede Einordnung des Beitrags Spekulation, und beide Leser liegen gleich weit von der Wahrheit entfernt."],"correctIndex":0,"explanation":"Beide Leser machen denselben Fehler: Sie entscheiden, bevor sie geprüft haben. Das Wort „Globalisten“ ist vage; wer damit gemeint ist, bleibt offen, und gerade diese Vagheit macht es unwiderlegbar und vielseitig einsetzbar. In verschwörungsfantastischen Zusammenhängen wird es in der Fachliteratur (Weiß 2024) als bekannter Code geführt, der an die alte antisemitische Erzählung von einer weltbeherrschenden Finanzmacht anknüpft, ohne Juden zu nennen. Das gibt dem Sprecher plausible Abstreitbarkeit. Chapelan (2024) hält zugleich fest, dass Verschwörungserzählungen ohne jüdischen Bezug nicht per se antisemitisch sind. Aus dem Wort allein folgt also weder ein sicherer Beleg für antisemitische Absicht noch das Gegenteil; man prüft Kontext und Belege. Die gute Prüfung fragt: Wer genau ist gemeint, und welcher Beleg stützt die Schuldzuweisung?","coreRule":"⚡ Entscheide bei einem vagen Reizwort nicht aus dem Bauch, sondern prüfe den Kontext: Welche Gruppe ist gemeint, welcher Beleg liegt vor, welches Bild steht dahinter?","beleg":"Werkstück G.2.1 (Funktion als Hundepfeife); Fn. gl-g-globalisten (Weiß 2024, S. 172; Chapelan 2024, S. 181)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Das Wort ist als Code bekannt, beweist aber allein noch keine Absicht. Der Fehler beider Leser ist, vor der Prüfung zu urteilen: Kontext und Belege zeigen, wer gemeint ist und was die Schuldzuweisung stützt.","prueffrage":"Welche Angaben über den Verfasser und den Zusammenhang des Beitrags lagen den beiden Lesern vor, als sie urteilten?","rueckmeldung":[{"option":1,"text":"Dass man ohne Beleg nichts unterstellen darf, stimmt. Nur den Wortlaut gelten zu lassen, geht aber am Kern vorbei, denn ein Code lebt davon, dass er nichts ausdrücklich nennt. Der Kontext lässt sich ohne Geständnis prüfen."},{"option":2,"text":"Der Schutzgedanke ist nachvollziehbar, und das Wort gilt tatsächlich als bekannter Code. Als Beweis taugt es allein aber nicht, denn nicht jede Verschwörungserzählung ist antisemitisch. Wer bis zum Gegenbeweis verurteilt, urteilt vor der Prüfung."},{"option":3,"text":"Aus dem Wort allein folgt tatsächlich kein sicheres Urteil. Spekulation ist die Einordnung aber nur, solange man nichts prüft: Wer gemeint ist und welche Belege es gibt, lässt sich klären. Beide Leser urteilen vorschnell."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Weiß, M. (2024): Impliziter Antisemitismus. In: Schuch, C. (Hg.): Antisemitismus und Recht. Bielefeld: transcript, 159–182 (CC BY 4.0)","oeffentlich":true,"doi":"10.14361/9783839466872-008","seite":"172"},{"typ":"doi","kurz":"Chapelan, A. (2024): Conspiracy Theories. In: Becker, M. J. u. a. (Hg.): Decoding Antisemitism. Cham: Palgrave Macmillan, 175–190 (CC BY 4.0)","oeffentlich":true,"doi":"10.1007/978-3-031-49238-9_13","seite":"181"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a7ac24b82ed1dba7"}},{"id":"qx-g-019","clusterId":"G","werkstueckRef":"G.2.1","stufe":4,"question":"Du sollst prüfen, ob dieser Beitrag seine Behauptung belegt. Was ist die zentrale Schwäche seiner Argumentation?","scenario":"Ein Beitrag reiht auf: steigende Energiepreise in Land A, ein Handelsabkommen in Land B, der Rücktritt eines Bankers in Land C – „alles Teil des Plans der Globalisten“. Dass die drei Ereignisse etwas miteinander zu tun haben, wird nirgends gezeigt, nur behauptet.","options":["Aus dem bloßen Nebeneinander der drei Ereignisse leitet der Beitrag einen gemeinsamen Plan ab, ohne dass er eine Verbindung zwischen ihnen belegt.","Der Beitrag zeigt nicht, wem die drei Ereignisse nützen, denn erst ein gemeinsamer Nutznießer würde aus den Vorfällen einen erkennbaren Plan machen.","Drei Ereignisse sind zu wenig, denn erst wenn sich viele solche Vorfälle in weiteren Ländern häufen würden, wäre ein gemeinsamer Plan belegt.","Die Ereignisse liegen in drei verschiedenen Ländern, und so weit voneinander entfernte Vorgänge können kaum von denselben Leuten gesteuert sein."],"correctIndex":0,"explanation":"Die Schwäche liegt im Schluss, nicht in den Einzelereignissen: Energiepreise, Handelsabkommen und Rücktritte können einzeln durchaus stimmen. Scheinbar unzusammenhängende Handlungen werden hier als Beweis für einen koordinierten Plan gedeutet; das Auge sucht eben Muster, auch im Rauschen (Apophenie). Belegt wäre ein Plan nur durch konkrete, überprüfbare Beweise für eine Absprache. Außerdem bleibt der „Plan der Globalisten“ so vage, dass jedes Ereignis nachträglich als Beweis passt und nichts ihn widerlegen könnte (Unfalsifizierbarkeit durch Vagheit). Gleichzeitigkeit ist noch keine Koordination.","coreRule":"⚡ Gleichzeitigkeit ist keine Koordination: Verlange den Beleg für die Verbindung, nicht nur für die Einzelereignisse.","beleg":"Werkstück G.2.1 (Die rhetorische Funktion: Unfalsifizierbarkeit durch Vagheit; Die transportierten Denkfehler: Apophenie)","status":"entwurf","kurz":"Der Beitrag stellt drei Ereignisse nebeneinander und erklärt sie zum Beweis für einen Plan, ohne eine Verbindung zu zeigen. Gleichzeitigkeit ist noch keine Koordination, und das Auge findet Muster auch im Rauschen.","prueffrage":"Welche Beteiligten haben die drei Ereignisse gemeinsam, und woran ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Ein gemeinsamer Nutznießer wäre ein sinnvoller Anhaltspunkt. Wer profitiert, muss aber nichts abgesprochen haben, und auch der Nutzen allein belegt keine Absprache. Dafür bräuchte es konkrete, überprüfbare Beweise."},{"option":2,"text":"Mehr Ereignisse zu sammeln, würde die Lücke nicht schließen: Auch viele Vorfälle nebeneinander zeigen nur ein Muster, nicht dessen Ursache. Dass drei Fälle wenig sind, stimmt, aber entscheidend ist die fehlende gezeigte Verbindung."},{"option":3,"text":"Entfernung macht eine Absprache zwar nicht unmöglich, und Koordination über Ländergrenzen hinweg kommt durchaus vor. Das Problem liegt anders: Der Beitrag belegt die Verbindung gar nicht, und dass er sie nicht belegt, heißt noch nicht, dass es sie nicht gibt."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"e03ad06baed2d98c"}},{"id":"qx-g-020","clusterId":"G","werkstueckRef":"G.2.2","stufe":1,"question":"Welcher Denkfehler steckt in dieser Aussage, und welche Gegenfrage deckt ihn am besten auf?","options":["Die Aussage fasst sehr unterschiedliche Redaktionen zu einer Stimme zusammen (Pauschalisierung). Eine gute Gegenfrage lautet: „Welche Medien meinst du konkret, und widersprechen sie einander wirklich nie?“","Die Aussage unterstellt bewusste Täuschung, wo auch ein Irrtum möglich ist (Unterstellung von Absicht). Eine gute Gegenfrage lautet: „Woher weißt du, dass sie bewusst lügen und sich nicht einfach nur irren?“","Die Aussage gibt einen persönlichen Eindruck als feststehende Tatsache aus (Behauptung ohne Beleg). Eine gute Gegenfrage lautet: „Hast du dafür einen Beleg, oder ist das vor allem dein Gefühl?“","Die Aussage ist bloß zugespitzt und meint ähnliche Berichte (Übertreibung). Eine gute Gegenfrage lautet: „Meinst du, dass sich die Redaktionen absprechen, oder nur, dass sie ähnlich berichten?“"],"correctIndex":0,"explanation":"„Die Medien“ ist ein Sammelbegriff für sehr viele Redaktionen mit unterschiedlichen Eigentümern, Zielgruppen und politischen Ausrichtungen. Wer sie zu einer einzigen, koordinierten Stimme verschmilzt, pauschalisiert und ignoriert Vielfalt und Konkurrenz: Zeitungen wie taz und NZZ oder New York Times und Wall Street Journal vertreten oft gegensätzliche Positionen. Die Gegenfrage zwingt zur Konkretisierung und macht die Behauptung überprüfbar. Dass einzelne Artikel Fehler enthalten können, ist damit nicht bestritten; es ist aber etwas anderes als eine pauschale Gleichschaltung aller Medien. Ein Pauschalurteil lässt sich nicht widerlegen, ein konkreter Fall dagegen schon.","coreRule":"⚡ „Die Medien“ gibt es nicht als eine Stimme, sondern als viele, die einander widersprechen.","beleg":"Werkstück G.2.2 (Die rhetorische Funktion, Punkt 3: Schaffung eines Strohmanns)","status":"entwurf","scenario":"Bei einem Familientreffen kommt das Gespräch auf Nachrichten. Ein Verwandter sagt: „Die Medien lügen doch alle dasselbe, die sind gleichgeschaltet.“","kurz":"„Die Medien“ sind viele Redaktionen mit gegensätzlichen Eigentümern und Positionen. Wer sie zu einer gleichgeschalteten Stimme verschmilzt, pauschalisiert. Die Frage nach konkreten Medien macht die Behauptung überprüfbar.","prueffrage":"Nennt der Verwandte für sein Urteil eine Quelle, ein Erlebnis oder eine Ursache, oder nur das Urteil selbst?","rueckmeldung":[{"option":1,"text":"Dass hier eine Absicht unterstellt wird, stimmt, und die Rückfrage ist nicht verkehrt. Sie lässt aber den Kern unberührt: Selbst wenn man Irrtum statt Lüge annähme, bliebe „alle Medien“ als eine einzige Stimme bestehen."},{"option":2,"text":"Ein Beleg fehlt tatsächlich, und danach zu fragen ist legitim. Die Frage bleibt aber so allgemein, dass der Verwandte mit einem einzelnen Beispiel antworten könnte, ohne dass die Verallgemeinerung auf „alle“ ins Wanken gerät."},{"option":3,"text":"Die Rückfrage trennt Absprache von ähnlicher Berichterstattung, und das kann sinnvoll sein. Doch die Aussage sagt „alle“ und „gleichgeschaltet“, behauptet also eine einzige koordinierte Stimme. Das ist mehr als Zuspitzung und blendet Konkurrenz und Vielfalt aus."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"bfa097b36195a611"}},{"id":"qx-g-021","clusterId":"G","werkstueckRef":"G.2.2","stufe":2,"question":"Welcher Denkfehler steckt in der Art, wie dein Onkel Meldungen bewertet?","scenario":"Dein Onkel sagt über Zeitungen und Fernsehsender: „Das stand in der Zeitung, also gelogen.“ Eine Meldung, die sein Weltbild stützt, lässt er dagegen als „seltene Ausnahme von gutem Journalismus“ gelten. Meldungen, die ihm widersprechen, wertet er als weiteren Beweis dafür, dass „die Lügenpresse“ eben lügt.","options":["Er kennt bei Meldungen nur „wahr“ oder „gelogen“ und lässt keinen Raum für Irrtümer, Fehler und Zwischenstufen.","Er verwirft Meldungen schon wegen ihrer Herkunft aus der Zeitung und prüft nicht, was in ihnen steht.","Er schert Zeitungen und Sender über einen Kamm und unterscheidet nicht zwischen einzelnen Redaktionen.","Er wertet Meldungen danach, ob sie zu seinem Weltbild passen, und nicht danach, was in ihnen steht."],"correctIndex":3,"explanation":"Der Onkel bewertet nicht den Inhalt einer Meldung, sondern nur, ob sie zu seinem Weltbild passt. Passende Meldungen gelten selbst dann als glaubwürdig, wenn sie aus derselben Quelle stammen, nur als „seltene Ausnahme“. Widersprechende Meldungen zählen als zusätzlicher Beweis für seine Sicht. So bestätigt jede Nachricht sein Weltbild, und keine kann es mehr korrigieren. Das ist ein Bestätigungsfehler. Ein pauschales Etikett wie „Lügenpresse“ verstärkt ihn, weil es als Filter wirkt: Es macht die Prüfung des einzelnen Artikels überflüssig. Dass er die Zeitungen als Ganzes verwirft, statt Meldungen zu prüfen, erinnert zwar an ein Ad hominem. Der Kern seines Fehlers ist aber, dass er je nach Weltbild unterschiedlich misst. Sinnvoll ist es, auf Spezifität zu bestehen: Welcher Artikel enthält welche überprüfbare Falschaussage, und wurde sie später korrigiert?","coreRule":"⚡ Wenn jede Nachricht danach gewertet wird, ob sie ins Weltbild passt, ist das keine Prüfung, sondern ein Filter.","beleg":"Werkstück G.2.2 (Die transportierten Denkfehler: Bestätigungsfehler)","status":"entwurf","kurz":"Der Onkel misst Meldungen nicht an ihrem Inhalt, sondern an seinem Weltbild: Passendes gilt als „Ausnahme“, Widersprechendes als Beweis. So bestätigt jede Nachricht seine Sicht, und keine kann sie mehr korrigieren.","prueffrage":"Was haben die Meldungen gemeinsam, die der Onkel gelten lässt, und aus welchen Quellen stammen sie?","rueckmeldung":[{"option":0,"text":"Dass er nur „wahr“ oder „gelogen“ kennt, stimmt. Der Kern liegt aber woanders: Auch mit Zwischenstufen könnte er noch nach Passung zu seinem Weltbild urteilen, statt nach dem Inhalt der Meldung."},{"option":1,"text":"Pauschal die Herkunft zu verwerfen, erinnert tatsächlich an ein Ad hominem. Er lässt aber passende Meldungen aus derselben Zeitung als „Ausnahme“ gelten, die Herkunft entscheidet also nicht, sondern die Passung zu seinem Weltbild."},{"option":2,"text":"Das Etikett „Lügenpresse“ über alle Redaktionen zu legen, ist pauschal und verstärkt das Problem als Filter. Es erklärt aber nicht, warum er Passendes als Ausnahme durchgehen lässt und Widersprechendes als Beweis zählt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"726e6cba39da7924"}},{"id":"qx-g-022","clusterId":"G","werkstueckRef":"G.2.2","stufe":3,"question":"Ein Bekannter sagt, ein Pauschalvorwurf wie „Lügenpresse“ sei doch bloß ein derber Ausdruck für Medienkritik und deshalb unproblematisch. Was ist die stärkste Gegenüberstellung?","options":["Der Ausdruck verwirft die Medien pauschal, statt einen konkreten Fehler zu benennen, und er war schon im Ersten Weltkrieg ein nationalistischer Kampfbegriff.","Der Ausdruck ist vor allem unhöflich, und wer Medien kritisieren will, erreicht mit einem sachlichen, genauen Ton mehr als mit einem derben Wort wie diesem.","Der Ausdruck unterstellt eine bewusste Lüge, wo auch ein schlichter Irrtum möglich ist, und wer von Lügen spricht, müsste Täuschungsabsicht nachweisen.","Der Ausdruck mag von der Meinungsfreiheit gedeckt sein, doch was man sagen darf, muss man nicht auch sagen, wenn es Journalistinnen und Journalisten verletzt."],"correctIndex":0,"explanation":"Berechtigte Medienkritik benennt einen konkreten Artikel, einen überprüfbaren Fehler und fragt, ob er korrigiert wurde. Ein Pauschalbegriff wie „Lügenpresse“ leistet das nicht: Er verwirft alle Quellen auf einmal und macht jede Gegeninformation von vornherein verdächtig. Dazu kommt die Herkunft des Wortes. Es ist älter als der Nationalsozialismus und war spätestens im Ersten Weltkrieg ein nationalistischer Kampfbegriff gegen die Presse. Die NS-Propaganda griff ihn auf und spitzte ihn antisemitisch zu, etwa gegen eine „jüdisch marxistische Lügenpresse“. Nach 1945 verschwand er weitgehend und wurde ab Oktober 2014 im Umfeld von Pegida wiederbelebt. Die Jury der Aktion „Unwort des Jahres“ wählte ihn im Januar 2015 zum Unwort des Jahres 2014, weil er Medien pauschal diffamiere und die für die Demokratie nötige Pressefreiheit gefährde, und verwies dabei ausdrücklich auf die NS-Vorgeschichte. Der Einwand „Das hat mit früher nichts zu tun“ ist also sachlich falsch. Das Problem liegt in der Generalanklage statt in der Kritik an konkreten Fehlern.","coreRule":"⚡ Ein Kampfbegriff hat eine Geschichte: Wer ihn benutzt, ruft sie mit auf.","beleg":"Werkstück G.2.2 (Historische Anknüpfung); Fn. gl-g-1 (Unwort des Jahres 2014, Jury-Begründung vom 13.01.2015; Begriffsgeschichte: Schmitz-Berning 2007, S. 327)","status":"entwurf","scenario":"Beim Abendessen verteidigt ein Bekannter den Ausdruck „Lügenpresse“: „Das ist halt zugespitzte Kritik. Wer Medien kritisiert, muss auch mal deutlich werden dürfen. Das hat doch mit früher nichts zu tun.“","kurz":"Berechtigte Kritik benennt einen konkreten, prüfbaren Fehler. „Lügenpresse“ verwirft dagegen alle Medien auf einmal, und das Wort hat eine Geschichte als Kampfbegriff, spätestens seit dem Ersten Weltkrieg. „Mit früher nichts zu tun“ stimmt also nicht.","prueffrage":"Seit wann ist „Lügenpresse“ als Schlagwort belegt, und wer hat es damals gegen wen benutzt?","rueckmeldung":[{"option":1,"text":"Ein sachlicher Ton überzeugt oft mehr, das stimmt. Doch die Kritik am Wort liegt tiefer als bei der Höflichkeit: Es verwirft alle Medien auf einmal, statt einen prüfbaren Fehler zu benennen, und hat eine belastete Geschichte."},{"option":2,"text":"Wer „Lüge“ sagt, unterstellt Absicht, das ist ein berechtigter Einwand. Er trifft aber nicht den Kern: Ein Fehler wäre mit Nachweis benennbar, das Wort verwirft jedoch alle Quellen pauschal. Zur Herkunft sagt der Einwand außerdem nichts."},{"option":3,"text":"Dass erlaubt und ratsam zweierlei sind, ist richtig. Der Bekannte verteidigt das Wort aber nicht als erlaubt, sondern als harmlose Kritik. Dagegen hilft der Sachbefund: Es ist ein Pauschalvorwurf mit Vorgeschichte als Kampfbegriff, nicht bloß eine Frage der Rücksicht."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schmitz-Berning, C. (2007): Vokabular des Nationalsozialismus. 2. Aufl. Berlin, New York: de Gruyter, s. v. „Journaille“","oeffentlich":false,"seite":"327"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c50aa7cdabfb0879"}},{"id":"qx-g-023","clusterId":"G","werkstueckRef":"G.2.2","stufe":4,"question":"Du sollst einschätzen, ob die Antwort des Sprechers berechtigte Medienkritik oder pauschale Delegitimierung ist. Welche Prüfung führt am besten zu einem begründeten Urteil?","scenario":"Nach einem Produktrückruf berichten mehrere Zeitungen kritisch über ein Unternehmen. Dessen Sprecher erklärt: „Das ist alles gekaufte Hetzpresse, da ist kein Wort wahr.“ Ein Artikel nennt einen konkreten Mangel mit Chargennummer, ein anderer enthält eine Zahl, die das Unternehmen für falsch hält.","options":["Man prüft, welche redaktionelle Linie die berichtenden Zeitungen zum Unternehmen haben, denn Häuser mit klarer Linie gewichten Rückrufe oft einseitig.","Man prüft den Ruf der Zeitungen, die den Mangel mit Chargennummer melden, denn etablierte Häuser machen seltener Fehler als unbekannte.","Man prüft, ob der Sprecher einen konkreten Artikel mit überprüfbarer Falschaussage zum Rückruf benennt und ob die Redaktion diese später korrigierte.","Man prüft, wie scharf die Berichte über den Rückruf formuliert sind, denn zugespitzte Sprache deutet oft auf Meinungsmache statt auf Information."],"correctIndex":2,"explanation":"Berechtigte Kritik hat eine Adresse: Welcher Artikel, wann, welche überprüfbare Falschaussage, und wurde sie korrigiert? Das lässt sich nachprüfen und im Zweifel widerlegen. Der Pauschalvorwurf „gekaufte Hetzpresse“ verwirft dagegen eine ganze Quelle wegen ihrer angeblichen Zugehörigkeit statt den einzelnen Beitrag zu prüfen, ein Ad Hominem. Jede Kritik, die von dort kommt, lässt sich dann als Bestätigung des eigenen Weltbildes abtun. Journalistische Fehler und Tendenzen zu leugnen wäre ebenso falsch; entscheidend ist die Spezifität. Die redaktionelle Linie einer Zeitung sagt nur, wie sie Themen gewichtet, nicht ob ein einzelner Satz zum Rückruf stimmt. Auch ein guter Ruf schützt nicht vor einem Fehler im konkreten Fall. Und ein scharfer Ton macht eine Aussage weder wahr noch falsch; dafür braucht es den konkreten Beleg.","coreRule":"⚡ Kritik an Medien hat eine Adresse: Artikel, Datum, Aussage, Korrektur.","beleg":"Werkstück G.2.2 (Das Anti-Denkmuster; Ad Hominem)","status":"entwurf","kurz":"Berechtigte Kritik benennt einen konkreten Beitrag mit prüfbarer Falschaussage und fragt nach einer Korrektur. Der Pauschalvorwurf „Hetzpresse“ verwirft dagegen die ganze Quelle, statt den einzelnen Beitrag zu prüfen.","prueffrage":"Wie lautet die Zahl, die das Unternehmen für falsch hält, und welche Zahl nennt es selbst?","rueckmeldung":[{"option":0,"text":"Dass Redaktionen Themen unterschiedlich gewichten, trifft zu. Die Linie sagt aber nur etwas über die Gewichtung, nicht darüber, ob die Angabe zum Mangel im einzelnen Artikel stimmt. Sie ersetzt die Prüfung des Beitrags nicht."},{"option":1,"text":"Ein guter Ruf spricht für Sorgfalt, ist aber kein Beleg im Einzelfall, denn auch etablierte Häuser irren sich. Zudem prüft man hier die Zeitung statt die Aussage, genau das Muster, das der Sprecher selbst zeigt."},{"option":3,"text":"Ein scharfer Ton wirkt wie ein Warnsignal. Er macht eine Aussage aber weder wahr noch falsch: Ein zugespitzter Bericht kann stimmen, ein nüchterner falsch sein. Entscheidend ist, ob die einzelne Angabe, etwa die Chargennummer, belegbar ist."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Presserat: Pressekodex (Fassung 19.03.2025), Ziffer 3 Richtigstellung","oeffentlich":true,"url":"https://www.presserat.de/pressekodex.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"4228af20e219bc6f"}},{"id":"qx-g-024","clusterId":"G","werkstueckRef":"G.2.3","stufe":1,"question":"Du liest in einem Forum: „Meine Heilpraktikerin sagt, die Schulmedizin behandelt nur Symptome, wir setzen auf ganzheitliche Heilung.“ Du fragst dich, ob das Wort „Schulmedizin“ hier neutral beschreibt oder etwas anderes tut. Woran erkennst du am besten, dass es hier als Kampfbegriff eingesetzt wird?","options":["Das Wort wird abwertend gebraucht und stellt die Medizin als starres System dar, damit die eigene Methode als überlegene Alternative erscheint.","Das Wort steht dem Gegenbegriff „ganzheitliche Heilung“ gegenüber, und schon diese Gegenüberstellung zweier Lager macht es zu einem Kampfbegriff.","Das Wort steht in einer unbelegten Aussage, denn es wird kein Grund dafür genannt, warum die Schulmedizin nur Symptome behandeln soll.","Das Wort stammt hier von einer Heilpraktikerin, und wer selbst eine andere Heilmethode anbietet, wird das Wort „Schulmedizin“ kaum neutral meinen."],"correctIndex":0,"explanation":"Überprüfe, wie das Wort gebraucht wird, nicht das Wort selbst: Wer „Schulmedizin“ abwertend verwendet (hier: „behandelt nur Symptome“) und die wissenschaftsbasierte Medizin als starres System darstellt, um die eigene Methode als überlegene Alternative zu positionieren, nutzt das Wort als Kampfbegriff. Dass das Wort allgemein gebräuchlich ist und sogar in Versicherungsbedingungen vorkommt, zeigt nur, dass es auch neutral verwendet werden kann. Darauf kommt es an: Wer spricht mit welcher Absicht, und was soll durch den Kontrast erreicht werden?","coreRule":"⚡ Entscheidend ist nicht das Wort, sondern wer es mit welcher Absicht abwertend einsetzt.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Einleitung und Punkt 3: Implizite Abwertung; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Das Wort „Schulmedizin“ ist im Deutschen allgemein gebräuchlich, es steht sogar in den Musterbedingungen privater Krankenversicherungen.","kurz":"Entscheidend ist, wie das Wort gebraucht wird: Es wertet ab („behandelt nur Symptome“) und zeichnet die Medizin als starres System, damit die eigene Methode überlegen wirkt. Dass das Wort sonst gebräuchlich ist, zeigt nur, dass es auch neutral stehen kann.","prueffrage":"Welche Eigenschaften schreibt der Forumsbeitrag jeder der beiden Behandlungsarten zu?","rueckmeldung":[{"option":1,"text":"Die Gegenüberstellung gehört hier zur Rhetorik, reicht aber allein nicht aus: Auch ein sachlicher Vergleich stellt zwei Ansätze gegenüber. Es kommt darauf an, ob das Wort dabei abwertet und die eigene Methode als überlegen erscheinen lässt."},{"option":2,"text":"Es stimmt, dass für die Behauptung kein Grund genannt wird. Das betrifft aber die Aussage, nicht die Rolle des Wortes: Auch eine belegte Behauptung könnte „Schulmedizin“ abwertend einsetzen. Ob es Kampfbegriff ist, zeigt sich am Gebrauch."},{"option":3,"text":"Dass die Heilpraktikerin eine andere Methode anbietet, kann ein Hinweis auf ihr Interesse sein, beweist aber nichts über den Wortgebrauch. Auch Menschen mit eigenem Angebot können das Wort neutral verwenden. Prüfe, wie es im Satz tatsächlich eingesetzt wird."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haufe: Schulmedizinklausel § 4 Abs. 6 MB/KK 94 ist wirksam (Kommentar)","oeffentlich":true,"url":"https://www.haufe.de/id/kommentar/schulmedizinklausel-4-abs-6-mbkk-94-ist-wirksam-HI947826.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Wuliger, M. (13.03.2017): Schulmedizin und arische Physik. Jüdische Allgemeine (Kolumne)","oeffentlich":true,"url":"https://www.juedische-allgemeine.de/kultur/schulmedizin-und-arische-physik/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Heissmann, N.; Weymayr, C. (2012): Die Homöopathie-Lüge, Teil 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1023a567a8bc3a8d"}},{"id":"qx-g-025","clusterId":"G","werkstueckRef":"G.2.3","stufe":2,"question":"Welche Antwort entkräftet die Behauptung am besten?","scenario":"Eine Bekannte sagt: „Die Schulmedizin hat seit hundert Jahren nichts dazugelernt, ich bleibe bei sanften Alternativen.“ Du möchtest ihr sachlich antworten, ohne sie bloßzustellen.","options":["Die Medizin kontrolliert ihre Mittel streng: Medikamente brauchen vor der Zulassung geprüfte Nachweise, und Behörden kontrollieren Hersteller und Praxen.","Die Medizin prüft ihre Annahmen systematisch und ändert sie, wenn Studien dagegensprechen: Theorien werden verworfen, Behandlungen verbessert.","Die Medizin gesteht ihre Grenzen offen ein: Nicht jede Krankheit ist heilbar, aber sanfte Alternativen stoßen bei vielen Leiden ebenso an Grenzen.","Die Medizin bildet ihren Nachwuchs sorgfältig aus: Ärztinnen und Ärzte durchlaufen ein langes Studium und haften für ihre Behandlungen."],"correctIndex":1,"explanation":"Die Behauptung „hat nichts dazugelernt“ ist eine Tatsachenbehauptung und lässt sich prüfen: Medizinische Lehrmeinungen werden regelmäßig revidiert, wenn bessere Studien vorliegen, und Behandlungen werden laufend verbessert. Das Wort „Schule“ weckt zwar das Bild von Auswendiglernen und Dogma, beschreibt aber eine Medizin, die es so nicht gibt, ein klassischer Strohmann. Eine gute Entgegnung widerlegt den Stillstandsvorwurf mit dem, was die Sache tatsächlich auszeichnet: systematische Selbstkorrektur. Strenge Kontrollen und Zulassungsregeln sind richtig, sagen aber nichts darüber, ob die Medizin dazulernt. Der Hinweis, dass auch die Alternativen an Grenzen stoßen, mag stimmen, widerlegt den Stillstandsvorwurf aber nicht, sondern weicht ihm aus. Und eine lange, sorgfältige Ausbildung belegt Sorgfalt, nicht Lernfähigkeit.","coreRule":"⚡ Prüfe, ob das Wort ein Bild erzeugt, das nicht zur Sache passt: „Schule“ suggeriert Stillstand, doch die Medizin korrigiert sich ständig selbst.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 1: Schaffung eines Strohmanns)","status":"entwurf","kurz":"Der Vorwurf behauptet Stillstand und lässt sich mit Tatsachen prüfen: Die Medizin verwirft Annahmen und verbessert Behandlungen, wenn Studien dagegensprechen. Der Fehler wäre, ein Bild von starrem „Schul“-Dogma zu bekämpfen, das so gar nicht existiert.","prueffrage":"Welche Behandlung von vor hundert Jahren wird heute noch genauso angewendet, und welche nicht mehr?","rueckmeldung":[{"option":0,"text":"Strenge Zulassung und Aufsicht sind richtig und wichtig. Sie sagen aber nichts darüber, ob die Medizin ihr Wissen verändert: Auch ein erstarrtes Fach könnte streng kontrolliert werden. Der Stillstandsvorwurf bleibt so unbeantwortet."},{"option":2,"text":"Offen zuzugeben, dass nicht alles heilbar ist, wirkt fair und nimmt der Bekannten den Wind aus den Segeln. Nur beantwortet das ihren Vorwurf nicht: Ob die Medizin dazulernt, bleibt offen. Der Hinweis auf die Grenzen der Alternativen lenkt davon eher ab."},{"option":3,"text":"Ein langes Studium und die Haftung stehen für Sorgfalt, und das ist durchaus ein Pluspunkt. Wer gründlich ausgebildet wird, lernt aber nicht automatisch dazu: Ausbildung vermittelt den heutigen Stand, sagt jedoch nicht, ob und wie er sich ändert."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Prasad, V. u. a. (2013): A decade of reversal: an analysis of 146 contradicted medical practices. Mayo Clin Proc 88(8), 790–798 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1016/j.mayocp.2013.05.012","url":"https://pubmed.ncbi.nlm.nih.gov/23871230/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3a45826f898ae7cf"}},{"id":"qx-g-026","clusterId":"G","werkstueckRef":"G.2.3","stufe":4,"question":"Was ist an dieser Rahmung der Debatte problematisch?","scenario":"Eine Zeitung kündigt eine Debatte an: „Schulmedizin gegen Alternativmedizin“ – zwei Gäste, je fünf Minuten Redezeit, kein Hinweis darauf, was Studien zur Wirksamkeit der jeweiligen Methoden zeigen.","options":["Sie lässt zu wenig Raum, denn fünf Minuten je Gast reichen kaum, um eine Heilmethode und ihre Begründung verständlich und angemessen darzustellen.","Sie ist zu schmal besetzt, denn zwei Gäste reichen kaum, um bei einem so breiten Thema die vielen verschiedenen Sichtweisen angemessen abzubilden.","Sie spitzt den Streit zu, denn das Wort „gegen“ macht aus einem Austausch einen Kampf, in dem es eher ums Gewinnen als ums Verstehen der Methoden geht.","Sie erzeugt falsche Ausgewogenheit, denn zwei Gäste mit je fünf Minuten verwischen den Unterschied zwischen nachgewiesener und fehlender Wirksamkeit."],"correctIndex":3,"explanation":"Die Gegenüberstellung zweier Gäste mit gleicher Redezeit suggeriert zwei gleichwertige, konkurrierende Schulen oder Philosophien. Das ist falsche Ausgewogenheit: Gleich viel Raum täuscht gleich viel Beleg vor. In der Realität gibt es Methoden, die ihre Wirksamkeit nach wissenschaftlichen Standards nachgewiesen haben, und Methoden, bei denen das nicht gelungen ist. Das ist ein Unterschied in der Beweislage, keine Frage der Weltanschauung. Auch das Wort „Schulmedizin“ in dieser Gegenüberstellung hilft nicht, denn es macht aus wissenschaftsbasierter Medizin eine bloße Denkschule unter mehreren. Falsch ist die Rahmung „zwei gleichwertige Seiten“, nicht das Thema.","coreRule":"⚡ Zwei Gäste sind noch keine zwei gleichwertigen Positionen: Frag nach der Evidenz hinter jeder Seite.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 2: Etablierung einer falschen Symmetrie)","status":"entwurf","kurz":"Gleiche Redezeit für beide Gäste suggeriert gleich viel Beleg, obwohl sich die Beweislage der Methoden unterscheidet. Der naheliegende Fehler ist, Ausgewogenheit mit Fairness gleichzusetzen, wo doch der Unterschied in den Belegen nichts mit Weltanschauung zu tun hat.","prueffrage":"Welche Gründe nennt die Ankündigung dafür, gerade diese beiden Seiten mit gleicher Redezeit gegenüberzustellen?","rueckmeldung":[{"option":0,"text":"Fünf Minuten sind für eine Heilmethode wirklich knapp. Das Problem bliebe aber bei zehn Minuten bestehen: Gleich lange Redezeit stellt beide Seiten als gleich gut belegt dar, obwohl die Studienlage unterschiedlich ist."},{"option":1,"text":"Bei einem so breiten Thema fehlen mit zwei Gästen sicher manche Stimmen. Mehr Gäste würden aber die Schieflage nicht beseitigen, denn dann stünden womöglich noch mehr Positionen scheinbar gleichwertig nebeneinander, ohne dass die Beweislage sichtbar wird."},{"option":2,"text":"Ein „gegen“ im Titel kann eine Debatte tatsächlich auf Sieg statt Verstehen trimmen. Entscheidend ist hier aber etwas anderes: Selbst bei freundlichem Ton würden zwei gleich behandelte Gäste vorspiegeln, die Methoden seien gleich gut belegt."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Koehler, D. J. (2016): Can journalistic “false balance” distort public perception of consensus in expert opinion? J Exp Psychol Appl 22(1), 24–38 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1037/xap0000073","url":"https://pubmed.ncbi.nlm.nih.gov/26752513/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"489e091f5c2c1576"}},{"id":"qx-g-027","clusterId":"G","werkstueckRef":"G.2.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ohne berechtigte Kritik an Konzernen wegzuwischen?","options":["Du fragst nach, welches Unternehmen oder welche Praktik konkret gemeint ist, und ob sich daraus auf alle Ärzte schließen lässt.","Du führst einen dokumentierten Fall von Industrieeinfluss an, der zeigt, dass der wahre Kern der Kritik berechtigt ist.","Du weist darauf hin, dass viele Medikamente nachweislich wirken, und fragst, ob die Person deshalb auf wirksame Behandlungen verzichten will.","Du fragst, welche persönliche Erfahrung mit einem Arzt hinter dem Misstrauen steckt, und gehst auf diese Erfahrung ein."],"correctIndex":0,"explanation":"Misstrauen gegenüber großen, mächtigen Konzernen ist eine gesunde demokratische Haltung, denn die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen. Der Denkfehler liegt erst in der pauschalen Verallgemeinerung: Aus berechtigter Kritik an einzelnen Missständen wird die Ablehnung der gesamten wissenschaftsbasierten Medizin und der individuellen Integrität vieler Ärzte und Forscher. Die Rückfrage nach dem konkreten Unternehmen oder Missstand erkennt den wahren Kern an und macht zugleich sichtbar, ob sich die Aussage überhaupt belegen lässt.","coreRule":"⚡ Misstrauen ist ein Werkzeug, es braucht aber eine Adresse, sonst wird es zum Pauschalurteil.","beleg":"Werkstück G.2.4 (Das Adaptive Talent; Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du willst weder so tun, als gäbe es keine Interessenkonflikte in der Industrie, noch die Pauschalaussage einfach stehen lassen.","quote":"","quoteLabel":"","kurz":"Die Rückfrage nach dem konkreten Unternehmen oder Missstand nimmt den berechtigten Kern der Kritik ernst und zeigt zugleich, ob sich die Aussage belegen lässt. Der Denkfehler liegt erst darin, aus einzelnen Missständen auf alle Ärzte zu schließen.","prueffrage":"Wie viele Ärzte kennt die Person persönlich, und von wie vielen weiß sie, dass sie Geld von Herstellern bekommen?","rueckmeldung":[{"option":1,"text":"Ein dokumentierter Fall zeigt, dass Kritik an der Industrie berechtigt sein kann. Er belegt aber nur diesen Einzelfall und prüft nicht, ob sich daraus auf alle Ärzte schließen lässt."},{"option":2,"text":"Dass viele Medikamente nachweislich wirken, stimmt. Das beantwortet aber nicht, ob die Pauschalaussage zutrifft, und es übergeht die berechtigte Kritik an Interessenkonflikten, statt sie ernst zu nehmen."},{"option":3,"text":"Die Frage nach der persönlichen Erfahrung ist einfühlsam und kann den Anlass des Misstrauens klären. Ob die Behauptung über alle Ärzte stimmt, bleibt dabei aber ungeprüft."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9e93df3eaf4fa23e"}},{"id":"qx-g-028","clusterId":"G","werkstueckRef":"G.2.4","stufe":2,"question":"Welche Antwort nimmt die Sorge ernst und regt zugleich zur Differenzierung an?","scenario":"Jemand sagt: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du möchtest das Gespräch offen halten.","options":["„Das klingt nach einer schlechten Erfahrung mit einem Arzt. Was genau ist dir passiert, dass du jetzt keinem mehr traust?“","„Medikamente werden von unabhängigen Behörden geprüft, bevor Ärzte sie verschreiben. Wusstest du, wie streng diese Zulassung abläuft?“","„Industrieeinfluss gibt es, dafür gibt es dokumentierte Fälle. Sind wirklich alle gekauft, oder meinst du bestimmte Praktiken?“","„Wem man vertraut, ist Ansichtssache, auch bei Ärzten und Pharmafirmen. Sollen wir das Thema stehen lassen, bevor wir uns streiten?“"],"correctIndex":2,"explanation":"Der Vorwurf enthält einen wahren Kern: Die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen (ein gut dokumentiertes Beispiel ist der Vioxx-Skandal). Hilfreich ist, den berechtigten Teil anzuerkennen und dann zu fragen, ob der Vorwurf für Millionen einzelner Ärzte und Forscher gilt oder für bestimmte, benennbare Praktiken. So wird aus dem Pauschalurteil eine prüfbare Behauptung. Zuzuhören und nach der Erfahrung mit einem Arzt zu fragen ist freundlich, lässt die Verallgemeinerung auf alle aber unberührt. Der Hinweis auf die Zulassungsprüfung stimmt, wehrt die Sorge aber ab, statt sie aufzugreifen. Die Haltung, Vertrauen sei Ansichtssache, beendet das Gespräch, statt die Behauptung prüfbar zu machen.","coreRule":"⚡ Nimm das Misstrauen ernst und frag nach dem Unterschied zwischen einzelnen Praktiken und Millionen von Menschen.","beleg":"Werkstück G.2.4 (Werkbank-Frage; Kontext & Tiefe)","status":"entwurf","kurz":"Der Vorwurf hat einen wahren Kern, etwa dokumentierte Fälle von Industrieeinfluss. Das erkennst du an und fragst dann, ob er für alle Ärzte gilt oder für bestimmte Praktiken. So wird aus dem Pauschalurteil eine prüfbare Behauptung.","prueffrage":"Wie reagiert jemand mit dieser Sorge vermutlich, wenn man ihm sagt, es gebe keinen Grund zum Zweifel?","rueckmeldung":[{"option":0,"text":"Nach der Erfahrung zu fragen ist freundlich und hält das Gespräch offen. Die Verallgemeinerung auf alle Ärzte und der berechtigte Kern des Vorwurfs bleiben dabei aber unberührt."},{"option":1,"text":"Dass unabhängige Behörden Zulassungen prüfen, stimmt. Die Antwort wehrt die Sorge aber ab, statt sie aufzugreifen, und erkennt nicht an, dass es Industrieeinfluss tatsächlich gibt."},{"option":3,"text":"Streit zu vermeiden ist ein verständliches Anliegen. Wer Vertrauen aber zur Ansichtssache erklärt und das Thema stehen lässt, beendet das Gespräch und macht die Behauptung nicht prüfbar."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0b73bf3c327b2377"}},{"id":"qx-g-029","clusterId":"G","werkstueckRef":"G.2.4","stufe":3,"question":"Was ist an dieser Reaktion problematisch?","scenario":"Eine Studie zu einem neuen Medikament wurde vom Hersteller finanziert. Ein Bekannter sagt: „Industriestudie – kann man vergessen.“","options":["Er hat im Kern recht, denn wer am Ergebnis verdient, hat einen Anreiz zur Schönfärberei, also taugt die Studie kaum.","Er urteilt zu früh, denn erst unabhängige Studien zum selben Medikament könnten zeigen, ob dieses Ergebnis trägt.","Er übersieht, dass auch unabhängige Forscher Interessen haben, also ist die Studie nicht weniger glaubwürdig als andere.","Er verwirft die Studie allein wegen ihrer Finanzierung, ohne vorher Methodik und Ergebnisse geprüft zu haben."],"correctIndex":3,"explanation":"Eine Finanzierung durch den Hersteller ist ein berechtigter Anlass, genauer hinzusehen: Wer von einem Ergebnis profitiert, hat einen Anreiz zur Schönfärberei. Die Herkunft des Geldes sagt aber noch nichts darüber, ob die Studie sauber gemacht wurde; das zeigt sich erst an Methodik und Ergebnissen. Wer jede industriefinanzierte Studie automatisch für ungültig erklärt, verwechselt Misstrauen mit Prüfung und urteilt über die Quelle statt über die Sache. Weitet man dieses Muster aus und tut ganze Forschungsfelder als „gekaufte Wissenschaft“ ab, kann es im Extremfall dazu führen, dass Menschen wirksame Behandlungen ablehnen. Entscheidend ist die Prüfung, nicht das Etikett.","coreRule":"⚡ Wer die Studie bezahlt hat, ist eine Frage an die Methode, kein Urteil über das Ergebnis.","beleg":"Werkstück G.2.4 (Red Flags; Kontext & Tiefe: Delegitimierung der Wissenschaft)","status":"entwurf","kurz":"Die Finanzierung ist ein guter Anlass, genauer hinzusehen, aber kein Beweis für schlechte Arbeit. Der Fehler liegt darin, die Quelle statt die Sache zu beurteilen: Ob die Studie taugt, zeigt sich erst an Methodik und Ergebnissen.","prueffrage":"Wie viele Teilnehmende hatte die Studie, gab es eine Vergleichsgruppe, und wer hat die Daten ausgewertet?","rueckmeldung":[{"option":0,"text":"Der Anreiz zur Schönfärberei besteht tatsächlich und ist ein Grund, genauer hinzusehen. Daraus folgt aber nicht, dass die Studie nichts taugt: Ob sie sauber gemacht wurde, zeigt sich nicht an der Herkunft des Geldes, sondern an ihrer Methodik."},{"option":1,"text":"Unabhängige Studien sind eine gute Ergänzung, doch man muss nicht auf sie warten. Methodik und Ergebnisse dieser Studie lassen sich schon jetzt prüfen. Der eigentliche Fehler ist, nach der Finanzierung statt nach der Qualität zu urteilen."},{"option":2,"text":"Auch unabhängige Forschende haben Interessen, das stimmt. Ein Interessenkonflikt beim Hersteller bleibt trotzdem ein berechtigter Anlass zur genaueren Prüfung. Die Studie ist deshalb nicht pauschal schlecht oder gut: Entscheidend ist, was die Prüfung ergibt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"4d1006c60a7d5b66"}},{"id":"qx-g-030","clusterId":"G","werkstueckRef":"G.2.4","stufe":4,"question":"Welcher Schritt in dieser Argumentation trägt nicht?","scenario":"Ein Beitrag schildert den gut dokumentierten Vioxx-Skandal: Ein Pharmaunternehmen hielt Hinweise auf Herzrisiken seines Schmerzmittels zu lange zurück. Daraus folgert der Beitrag: „Also unterdrückt die ganze Branche längst Heilmittel gegen Krebs.“","options":["Ein belegter Einzelfall wird zum Beweis für ein verdecktes Vorgehen der ganzen Branche erklärt (voreilige Verallgemeinerung).","Ein Skandal um ein Schmerzmittel wird ohne Weiteres auf das ganz andere Gebiet der Krebsmedizin übertragen (Themenwechsel).","Ein vergangener Skandal wird angeführt, obwohl er über das heutige Verhalten der Branche wenig aussagt (veralteter Beleg).","Der Skandal zählt als Beleg, obwohl gerade seine Aufdeckung eher gegen eine dauerhafte Vertuschung spricht (übersehenes Gegenargument)."],"correctIndex":0,"explanation":"Die Branche hat einen wahren Kern, den man nicht wegreden muss: Sie ist profitorientiert, und es gibt nachgewiesenes Fehlverhalten. Ein belegter Missstand eines Unternehmens ist deshalb legitime Kritik. Der Fehler liegt im Sprung: Ein Einzelfall belegt den Einzelfall. Dass die ganze Branche Heilmittel gegen Krebs unterdrückt, folgt daraus nicht. Der reale Skandal dient hier als Hebel für die viel größere Verschwörungserzählung, dass „Big Pharma“ Heilmittel unterdrückt.","coreRule":"⚡ Ein belegter Einzelfall trägt nur den Einzelfall, nicht ein ganzes System.","beleg":"Werkstück G.2.4 (Kontext & Tiefe; Anwendung & Relevanz: In Verschwörungsmythen; Schmiede-Übung)","status":"entwurf","kurz":"Ein belegter Missstand eines Unternehmens belegt zunächst nur diesen Einzelfall. Der Sprung zur ganzen Branche und zu unterdrückten Krebsheilmitteln ist das Problem: Ein realer Skandal dient als Hebel für eine viel größere Behauptung, die daraus nicht folgt.","prueffrage":"Was genau zeigt der Vioxx-Fall, und was davon hat mit Krebsmitteln zu tun?","rueckmeldung":[{"option":1,"text":"Der Wechsel vom Schmerzmittel zur Krebsmedizin fällt tatsächlich auf. Er ist aber nur ein Teil des Problems: Selbst bei einem Krebsmittel würde ein Einzelfall nicht zeigen, dass die ganze Branche Heilmittel unterdrückt."},{"option":2,"text":"Wie alt der Skandal ist, nennt das Szenario gar nicht, und darauf kommt es auch nicht an. Selbst ein ganz aktueller Fall würde nur sich selbst belegen, nicht das Verhalten einer ganzen Branche."},{"option":3,"text":"Dass der Skandal ans Licht kam, ist durchaus bemerkenswert und spricht nicht für lückenlose Vertuschung. Der Beitrag nutzt den Fall aber vor allem für einen viel weiteren Schluss, und dort liegt der tragende Fehler: bei der Ausweitung vom Einzelfall."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"babeaaacc12bd691"}},{"id":"qx-g-031","clusterId":"G","werkstueckRef":"G.3.1","stufe":1,"question":"Du prüfst die Werbung. Welche Rückfrage deckt am besten auf, ob die Rede von „Toxinen“ und „Schlacken“ überhaupt etwas Konkretes behauptet?","options":["Wurde die Saftkur mit einer Scheinkur verglichen, und wie unterschieden sich beide Gruppen am Ende bei den Beschwerden?","Wie heißt jeder gemeinte Stoff chemisch, und wie wurde seine Menge im Körper vor und nach der Saftkur gemessen?","Welche Nebenwirkungen der Saftkur sind bekannt, und ab wie vielen Tagen ohne feste Nahrung gilt sie als bedenklich?","Wer verdient an der Saftkur, und wie unabhängig sind die Personen, die sie in der Werbung als wirksam empfehlen?"],"correctIndex":1,"explanation":"Die Wörter klingen nach Wissenschaft, benennen aber keine bestimmte Substanz. „Toxin“ stammt aus der Toxikologie und wird hier zum Sammelbegriff für alles Unbestimmte, was als schädlich empfunden wird. „Schlacken“ stammt aus der Metallurgie und ist auf den Körper übertragen worden; biologisch gibt es sie nicht. Eine Behauptung ohne benennbaren Stoff lässt sich weder messen noch widerlegen. Die Rückfrage nach Name und Messung zwingt die Werbung, Konkretes zu liefern. Tatsächlich fand eine Übersichtsarbeit von 2015 für kommerzielle Detox-Diäten keine überzeugenden Belege, weder für die Ausscheidung von Toxinen noch für Gewichtsmanagement.","coreRule":"⚡ Ein Begriff, der sich nicht chemisch benennen lässt, beschreibt keine Substanz, sondern ein Gefühl.","beleg":"Werkstück G.3.1 (Kontext & Tiefe: Pseudowissenschaftliche Umdeutung; Fn. gl-g-detox, Klein/Kiat 2015)","status":"entwurf","scenario":"Eine Werbeanzeige für eine „Detox-Saftkur“ verspricht, „Toxine und Schlacken“ auszuleiten, die sich durch Umwelt und Ernährung im Körper angesammelt hätten. Welche Stoffe genau gemeint sind, steht nirgends.","kurz":"Wer nach Namen und Messung fragt, zwingt die Werbung zu Konkretem. „Toxine“ und „Schlacken“ klingen nach Wissenschaft, benennen aber keine bestimmte Substanz. Was sich nicht benennen lässt, lässt sich weder messen noch widerlegen.","prueffrage":"Welchen einzigen Stoff aus der Anzeige könntest du morgen im Labor suchen lassen?","rueckmeldung":[{"option":0,"text":"Ein Vergleich mit einer Scheinkur ist ein guter Test. Er greift aber erst, wenn feststeht, was gemessen werden soll. Beschwerden sagen nichts darüber, ob „Toxine“ und „Schlacken“ überhaupt etwas Bestimmtes meinen."},{"option":2,"text":"Nebenwirkungen zu kennen ist für die Sicherheit wichtig. Die Frage prüft aber nicht, ob die versprochene Ausleitung einen bestimmten Stoff meint. Die Begriffe selbst bleiben dabei unberührt."},{"option":3,"text":"Interessen und Unabhängigkeit der Empfehlenden sind für die Glaubwürdigkeit der Werbung bedeutsam. Einen Stoff benennt diese Frage trotzdem nicht. Ob „Toxine“ und „Schlacken“ etwas Konkretes behaupten, bleibt offen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"861b34f6f5dc5dc7"}},{"id":"qx-g-032","clusterId":"G","werkstueckRef":"G.3.1","stufe":2,"question":"Was folgt aus deiner Beobachtung für die Behauptung, die Kur habe Giftstoffe aus deinem Körper ausgeleitet?","scenario":"Nach drei Tagen einer teuren Detox-Saftkur fühlst du dich leichter und „reiner“. Du hast dafür bezahlt, du glaubst an die Wirkung, und du hast drei Tage lang kaum etwas gegessen. Du fragst dich, ob dein gutes Gefühl beweist, dass die Kur Giftstoffe ausgeleitet hat.","options":["Nichts Verlässliches: Nach drei Tagen mit kaum Essen und bezahlter Erwartung kann das Gefühl andere Gründe haben, es zeigt nicht, welcher Stoff ausgeleitet wurde.","Es spricht für die Wirkung: Dass du dich nach drei Tagen Saftkur besser fühlst, entspricht einer Beobachtung, die bei Medikamenten oft vor der Erklärung des Mechanismus stand.","Es belegt die Wirkung wenigstens für dich: Nach drei Tagen Saftkur kannst nur du beurteilen, wie du dich fühlst, und dein Eindruck zählt daher als Beleg.","Es macht die Wirkung wahrscheinlich: Weil du drei Tage kaum etwas gegessen hast, konnte dein Körper Altes abbauen, und das leichte Gefühl zeigt diesen Abbau an."],"correctIndex":0,"explanation":"Ein gutes Gefühl ist ein schwacher Beleg: Wer Geld für eine Kur ausgibt und an sie glaubt, fühlt sich oft schon deshalb besser (Erwartungs- bzw. Placebo-Effekt). Dazu kommt, dass du drei Tage kaum etwas gegessen hast, und wer wenig isst, fühlt sich oft schon dadurch leichter. Um eine Ausleitung zu zeigen, müsste man den Stoff benennen und seine Konzentration vor und nach der Kur messen; ein Gefühl, auch ein lang anhaltendes, leistet das nicht. Schädliche Substanzen baut vor allem die Leber ohnehin ständig ab, und die Nieren scheiden viele davon aus. Eine Übersichtsarbeit von 2015 (Klein/Kiat) fand zu kommerziellen Detox-Diäten keine randomisierten kontrollierten Studien am Menschen und keine überzeugende Evidenz für die Ausleitung von Toxinen. Dass Wirkungen manchmal vor ihrem Mechanismus beobachtet wurden, stimmt, setzt aber eine verlässlich festgestellte Wirkung voraus, kein bloßes Gefühl. Dein Eindruck ist für dein Befinden maßgeblich, nicht aber dafür, was im Körper geschehen ist.","coreRule":"⚡ Ein gutes Gefühl nach einer Kur belegt nicht, dass ein Gift ausgeleitet wurde: Dafür braucht es einen benannten Stoff und eine Messung davor und danach.","beleg":"Werkstück G.3.1 (Red Flags; Verbindungen: Placebo); Fn. gl-g-detox (Klein/Kiat 2015, J Hum Nutr Diet 28(6), S. 675–686)","status":"entwurf","kurz":"Das Gefühl allein sagt nicht, was im Körper passiert ist: Bezahlte Erwartung und drei Tage kaum Essen können es erklären. Der naheliegende Fehler ist, vom Eindruck auf eine Ausleitung zu schließen, die man nur durch Messen eines Stoffs zeigen könnte.","prueffrage":"Was hast du in den drei Tagen außer den Säften anders gemacht als sonst, und wie fühlt sich das gewöhnlich an?","rueckmeldung":[{"option":1,"text":"Dass Wirkungen manchmal vor ihrer Erklärung beobachtet wurden, stimmt. Dort stand aber eine verlässlich festgestellte Wirkung am Anfang. Hier gibt es nur ein Gefühl, das sich auch anders erklären lässt."},{"option":2,"text":"Wie du dich fühlst, kannst nur du beurteilen, und dafür zählt dein Eindruck. Gefragt ist aber, ob Giftstoffe ausgeleitet wurden, und das zeigt ein Gefühl nicht, auch wenn es echt ist."},{"option":3,"text":"Dass man sich bei wenig Essen leichter fühlt, ist gut möglich. Das erklärt aber nur das Gefühl und belegt keinen Abbau von „Altem“ oder gar von Giftstoffen. Dafür müsste man einen Stoff vor und nach der Kur messen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b776d31fd7e5927f"}},{"id":"qx-g-033","clusterId":"G","werkstueckRef":"G.3.1","stufe":3,"question":"Bei wem wird aus einer harmlosen Angewohnheit ein echtes Problem?","options":["Ein Mann trinkt drei Tage nur Säfte, weil er sich danach leichter fühlt, und geht anschließend wie geplant zur Kontrolle bei seinem Hausarzt.","Eine Frau hat seit Stunden Erbrechen und Krämpfe nach einem Pilzgericht und setzt auf eine Detox-Kur statt auf ärztliche Hilfe.","Eine Studentin gibt für die Kur mehr Geld aus als geplant und ärgert sich, weil sie nach drei Tagen vor allem hungrig war.","Eine Rentnerin mit Bluthochdruck trinkt täglich „Detox“-Tee und nimmt ihre verordneten Tabletten trotzdem unverändert weiter."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob jemand Geld ausgibt, ob ein Produkt wissenschaftlich klingt oder ob eine Kur unwirksam ist, sondern was sie ersetzt. Eine Saftkur, die man macht, weil man sich danach besser fühlt, bleibt meist harmlos: Das Gefühl ist echt, die behauptete „Entgiftung“ nicht, aber der Schaden ist gering. Gefährlich wird es, wenn ein unwirksames Produkt an die Stelle wirksamer Hilfe tritt. Bei einer realen Vergiftung zählt jede Stunde, und ein Produkt, dessen Wirkung über die natürliche Entgiftung durch Leber und Nieren hinaus nicht nachgewiesen ist, kostet dann Zeit, die für eine echte Behandlung fehlt. Der Mann geht trotz Kur zur ärztlichen Kontrolle, die Kur ersetzt also nichts. Der Ärger über Geld oder Hunger ist ein Verbraucherproblem, kein Gesundheitsrisiko. Die Frau mit Bluthochdruck nimmt ihre Tabletten weiter, der Tee tritt also nicht an die Stelle einer wirksamen Behandlung.","coreRule":"⚡ Harmlos ist das Ritual, gefährlich ist der Ersatz für echte Behandlung.","beleg":"Werkstück G.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Personen nutzen „Detox“-Produkte, deren Anbieter versprechen, „Schlacken“ und Giftstoffe aus dem Körper auszuleiten.","kurz":"Problematisch wird ein unwirksames Produkt erst dort, wo es wirksame Hilfe ersetzt. Bei einer akuten Vergiftung geht dadurch Zeit verloren. Unwirksamkeit, Kosten oder wissenschaftlicher Anschein allein machen es nicht gefährlich.","prueffrage":"Was hätte jede der vier Personen ohne die Kur stattdessen getan, und was hätte ihr das gebracht?","rueckmeldung":[{"option":0,"text":"Die behauptete „Entgiftung“ ist unbelegt, daran ändert die Saftkur nichts. Hier aber geht der Mann wie geplant zur Kontrolle beim Hausarzt, die Kur ersetzt also keine Hilfe. Das gute Gefühl danach ist echt, der Schaden meist gering."},{"option":2,"text":"Mehr Geld ausgegeben und drei Tage gehungert zu haben, ist ärgerlich, die Kur hat sich für sie nicht gelohnt. Es ist aber ein Verbraucherproblem: Es geht weder eine Behandlung verloren noch droht ein größerer gesundheitlicher Schaden."},{"option":3,"text":"Ein Tee mit unbelegter Wirkung wirkt neben einer Erkrankung schnell verdächtig. Sie nimmt ihre verordneten Tabletten aber unverändert weiter, der Tee tritt also nicht an die Stelle der wirksamen Behandlung."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NCCIH (NIH): Detoxes and Cleanses: What You Need To Know (Stand März 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"8889f90bf87eee83"}},{"id":"qx-g-034","clusterId":"G","werkstueckRef":"G.3.1","stufe":4,"question":"Mit welchem einfachen Versuch prüfst du am besten, ob die Verfärbung wirklich ausgeleitete Giftstoffe zeigt?","scenario":"Eine Werbung verspricht: Ein Detox-Fußpflaster zieht über Nacht Giftstoffe aus dem Körper, am Morgen ist es dunkel verfärbt. Als „Beweis“ wird die braune Verfärbung gezeigt. Viele dieser Pflaster enthalten getrockneten Holzessig, der Feuchtigkeit anzieht.","options":["Das Pflaster über Nacht auf frisch gewaschenem Fuß tragen: Fällt die braune Farbe schwächer aus, stammt sie von Schmutz, nicht von Giftstoffen.","Das Pflaster eine Nacht am Fuß und eine am Unterarm tragen: Färbt es sich an beiden Stellen braun, stammen Giftstoffe aus dem ganzen Körper.","Das Pflaster von jemandem tragen lassen, der den Zweck nicht kennt (Verblindung): Verfärbt es sich trotzdem braun, ist die Wirkung echt.","Ein unbenutztes Pflaster über Nacht Feuchtigkeit und Wärme aussetzen: Verfärbt es sich auch ohne Fuß braun, beweist die Farbe nichts."],"correctIndex":3,"explanation":"Ein guter Test widerlegt nicht einfach die Behauptung, sondern baut eine einfache Alternativerklärung und prüft sie: Wenn die Verfärbung auch ohne Körper entsteht, kann sie kein Beleg für ausgeleitete Giftstoffe sein. Der Gegenversuch ist leicht durchführbar: ein paar Tropfen Wasser auf ein unbenutztes Pflaster, eine Tasse heißen Tee darauf stellen und zehn Minuten warten. Ein frisch gewaschener Fuß prüft nur, ob Schmutz mitspielt, nicht ob Feuchtigkeit allein die Farbe erzeugt. Am Fuß und am Unterarm färbt sich das Pflaster beide Male, weil auch dort Feuchtigkeit herankommt, über Giftstoffe sagt das nichts. Verblindung hilft gegen Erwartungseffekte, eine Farbe ist aber ohnehin sichtbar; offen bleibt die Alternativerklärung, nicht die Erwartung.","coreRule":"⚡ Baue die einfachste Alternativerklärung und teste sie, bevor du an eine Entgiftung glaubst.","beleg":"Werkstück G.3.1 (Werkbank-Frage; Red Flags); Fn. gl-g-6 (Goldacre 2008, Bad Science, Kap. 1 „Matter“)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Entsteht die Verfärbung auch an einem unbenutzten Pflaster mit nur Feuchtigkeit und Wärme, kann sie keine ausgeleiteten Giftstoffe zeigen. Der Fehler: die Farbe als Beweis zu nehmen, ohne eine einfache Alternativerklärung zu prüfen.","prueffrage":"Welche Zutat des Pflasters könnte sich über Nacht auch ohne Giftstoffe verfärben, und wodurch?","rueckmeldung":[{"option":0,"text":"Mit gewaschenem Fuß lässt sich prüfen, ob Schmutz mitspielt. Ob Feuchtigkeit allein die Farbe erzeugt, bleibt aber offen, und eine schwächere Farbe sagt nichts darüber, ob Giftstoffe im Spiel sind."},{"option":1,"text":"Ein Vergleich zweier Körperstellen wirkt wie eine Kontrolle. Auch am Unterarm kommt aber Feuchtigkeit ans Pflaster, die Farbe an beiden Stellen passt also ebenso zur Feuchtigkeitserklärung und belegt keine Giftstoffe aus dem ganzen Körper."},{"option":2,"text":"Verblindung hilft, wo Erwartungen das Ergebnis färben, etwa beim Wohlbefinden. Eine Verfärbung sieht aber jeder, unabhängig von der Erwartung; ungeprüft bleibt, ob Feuchtigkeit allein sie auslöst."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Goldacre, B. (2008): Bad Science. London: Fourth Estate, Kap. 1 „Matter“ (dt. Die Wissenschaftslüge, 2010)","oeffentlich":false},{"typ":"url","kurz":"Federal Trade Commission (28.01.2009): FTC Charges Marketers of Kinoki Foot Pads With Deceptive Advertising","oeffentlich":true,"url":"https://www.ftc.gov/news-events/news/press-releases/2009/01/ftc-charges-marketers-kinoki-foot-pads-deceptive-advertising-seeks-funds-consumer-redress","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a7475ba6fbca05e0"}},{"id":"qx-g-035","clusterId":"G","werkstueckRef":"G.3.2","stufe":1,"question":"Ein Homöopath sagt: „Wasser hat ein Gedächtnis. Ein Tropfen Ursubstanz hinterlässt in der Verdünnung seine Information, und die wirkt dann heilend.“ Welcher Einwand trifft die Behauptung am stärksten?","options":["Hätte Wasser ein Gedächtnis, trüge es auch die Informationen aus seiner ganzen früheren Geschichte; warum es nur die letzte behalten soll, bleibt unerklärt.","Wasser kann Informationen nur kurz behalten, sodass die Wirkung eines Mittels schon nach wenigen Minuten wieder verschwinden würde, lange bevor jemand es einnimmt.","Von einem Tropfen Ursubstanz ist nach der Verdünnung kaum etwas übrig; eine so winzige Menge reicht nicht aus, um im Körper eine heilende Wirkung auszulösen.","Selbst wenn Wasser eine Information speichern könnte, wäre noch nicht gezeigt, dass gerade diese Information im Körper heilt; das müsste eigens geprüft werden."],"correctIndex":0,"explanation":"Das Wasser der Erde ist seit Jahrmillionen im Kreislauf und hatte unzählige Kontakte. Wer behauptet, es „erinnere“ sich ausgerechnet an die letzte „Information“ und vergesse alle anderen, muss einen Mechanismus nennen, der das Vergessen steuert; ohne ihn gilt die Behauptung nur für den einen Fall, den man gerade braucht. Der Einwand zur Dauer zielt physikalisch in eine richtige Richtung, denn Strukturen im flüssigen Wasser ordnen sich in Billionstelsekunden um, nicht erst nach Minuten; so formuliert räumt er aber ein, dass Wasser überhaupt Informationen speichert. Den Kern trifft nur der Widerspruch in einem Gedächtnis, das nichts vergisst und doch gezielt eine einzige Information trägt.","coreRule":"⚡ Ein Gedächtnis, das nichts vergisst, kann nicht gezielt eine einzige Information tragen.","beleg":"Werkstück G.3.2 (Die Wasserleiche; Aktivierungs-Frage)","status":"entwurf","scenario":"Das Wasser, aus dem ein homöopathisches Mittel hergestellt wird, war schon im Ozean, im Körper von Dinosauriern, in Kläranlagen, in Wolken, in Pflanzen und im Blut von Menschen. Es hat also unzählige Kontakte hinter sich. Jetzt wird es mit einem Tropfen Ursubstanz „informiert“.","kurz":"Ein Gedächtnis, das nichts vergisst, müsste auch alle früheren Kontakte des Wassers tragen. Wer behauptet, nur die letzte „Information“ bleibe, braucht einen Mechanismus fürs gezielte Vergessen; ohne ihn gilt die Idee nur für den Fall, den man gerade braucht.","prueffrage":"Wie viele Stoffe hat dasselbe Wasser vor dem Tropfen schon berührt, und welche davon spielen in der Behauptung eine Rolle?","rueckmeldung":[{"option":1,"text":"Dass sich Wasserstrukturen in Billionstelsekunden umordnen, stimmt, nicht erst nach Minuten. Der Einwand räumt aber ein, Wasser speichere Informationen, nur eben kurz, und lässt offen, warum es dann ausgerechnet die letzte behalten soll."},{"option":2,"text":"In hohen Potenzen ist tatsächlich kaum noch Ursubstanz vorhanden. Der Homöopath sagt aber gerade, nicht der Stoff wirke, sondern die Information; damit geht dieser Einwand an der Behauptung vorbei, statt ihren Kern zu treffen."},{"option":3,"text":"Dass eine Wirkung eigens geprüft werden müsste, ist berechtigt. Der Satz nimmt aber zunächst an, Wasser könne Information speichern, und übergeht so den Widerspruch eines Gedächtnisses, das nichts vergisst und doch nur eine Information trägt."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roth, K. (2013): Vitalisiert, verwirbelt, levitiert, energetisiert, informiert und anti-entropisch H2O – Jo mei! Chemie in unserer Zeit 47, 108–121","oeffentlich":false,"doi":"10.1002/ciuz.201300626"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ac11a7e163af7fa3"}},{"id":"qx-g-036","clusterId":"G","werkstueckRef":"G.3.2","stufe":2,"question":"Welches Ergebnis dieser Wiederholung würde die Behauptung „Wasser speichert Information“ am stärksten untergraben?","scenario":"Ein Bekannter verweist dich auf eine Veröffentlichung in „Nature“ von 1988. Ein französischer Forscher berichtete dort, stark verdünnte Antikörper wirkten noch auf weiße Blutzellen, und das soll belegen, dass Wasser ein „Gedächtnis“ hat. In seinem Labor wurde der Versuch anschließend wiederholt, diesmal mit Proben, deren Inhalt die Auswertenden nicht kannten (verblindet).","options":["Der Effekt verschwindet, sobald die Antikörperlösungen anders gelagert werden.","Der Effekt verschwindet, sobald die Auswertenden nicht wissen, welche Probe welche ist.","Der Effekt verschwindet, sobald man statt weißer Blutzellen andere Zellen untersucht.","Der Effekt bleibt bei verblindeter Auswertung erkennbar, fällt aber schwächer aus als zuvor."],"correctIndex":1,"explanation":"Wenn ein Effekt nur auftritt, solange die Auswertenden die Proben kennen, liegt die Ursache nahe bei den Erwartungen der Beobachter und nicht beim Wasser. Genau so verlief der Fall: Der Biomediziner Jacques Benveniste meldete 1988 in „Nature“ Effekte extrem verdünnter Antikörper auf weiße Blutzellen, doch bei der Nachprüfung in seinem Labor verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Ein Befund, der davon abhängt, ob jemand die Probenzuordnung kennt, ist kein belastbarer Beleg für eine Eigenschaft des Wassers. Dagegen würde ein Effekt, der auch verblindet bestehen bleibt, die Behauptung stützen. Ein Effekt, der bei anderer Lagerung der Antikörperlösungen verschwindet, zeigt nur, dass er empfindlich ist, nicht dass er auf Erwartungen beruht. Verschwindet er bei einer anderen Zellsorte, schränkt das höchstens ein, wo er auftritt. Und ein verblindet bestehender, wenn auch schwächerer Effekt spricht eher für die Behauptung als gegen sie.","coreRule":"⚡ Ein Effekt, der verschwindet, wenn niemand weiß, welche Probe welche ist, trägt keine Theorie.","beleg":"Werkstück G.3.2 (Kontext & Tiefe: Unfalsifizierbarkeit); Fn. gl-g-4 (Davenas u. a. 1988, Nature 333, S. 816–818; Maddox/Randi/Stewart 1988, Nature 334, S. 287–290)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Verschwindet ein Effekt, sobald die Auswertenden die Proben nicht mehr kennen, lag er wohl an deren Erwartungen und nicht am Wasser. Naheliegend ist, jede Abhängigkeit von Bedingungen als Widerlegung zu lesen, doch erst die Verblindung trennt Erwartung von Wirkung.","prueffrage":"Mit welchem Ergebnis der Wiederholung wäre zu rechnen, wenn das Wasser in Wahrheit gar nichts speichert?","rueckmeldung":[{"option":0,"text":"Dass der Effekt auf die Lagerung reagiert, wirkt wie ein Mangel. Es zeigt aber nur, dass er empfindlich ist. Mit den Erwartungen der Auswertenden hat das nichts zu tun, und die Behauptung wird dadurch nicht widerlegt."},{"option":2,"text":"Bleibt der Effekt bei anderen Zellen aus, weist das auf einen begrenzten Geltungsbereich hin. Das schränkt höchstens ein, wo er auftritt, und belegt nicht, dass er auf Erwartungen beruht oder gar nicht existiert."},{"option":3,"text":"Ein etwas schwächerer Effekt nach der Verblindung kann wie ein Warnsignal wirken. Bleibt er aber erkennbar bestehen, spricht das eher für die Behauptung als gegen sie, denn ein erwartungsbedingter Effekt wäre verschwunden."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Davenas, E. u. a. (1988): Human basophil degranulation triggered by very dilute antiserum against IgE. Nature 333, 816–818","oeffentlich":false,"doi":"10.1038/333816a0"},{"typ":"doi","kurz":"Maddox, J.; Randi, J.; Stewart, W. W. (1988): „High-dilution“ experiments a delusion. Nature 334, 287–290","oeffentlich":false,"doi":"10.1038/334287a0"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"1494fdf4d5b06a7a"}},{"id":"qx-g-037","clusterId":"G","werkstueckRef":"G.3.2","stufe":3,"question":"Was ist an der Antwort des Beraters der entscheidende Denkfehler?","options":["Die Behauptung wird erst nachträglich eingeführt, um den Widerspruch zur fehlenden Substanz abzufangen, und lässt sich mit keinem Instrument prüfen.","Die Behauptung widerspricht sich selbst, denn eine immaterielle Wirkung kann nicht in einem Stoff stecken, der wie Wasser ganz aus Materie besteht.","Die Behauptung schreibt dem Wasser die menschliche Fähigkeit zu, sich etwas zu merken, und verwechselt so ein Bild aus dem Alltag mit einem Vorgang.","Die Behauptung ist bisher bloß unbelegt; fände man ein Messverfahren für das Gedächtnis des Wassers, wäre die Antwort des Beraters eine ausreichende Erklärung."],"correctIndex":0,"explanation":"Die Zusatzannahme „Information im Wasser“ wurde nicht aus Beobachtungen abgeleitet, sondern soll nur den Widerspruch auflösen, dass in stark verdünnten Mitteln (jenseits von etwa C12) kein Molekül der Substanz mehr enthalten ist. Solange diese Information mit keinem Instrument gemessen werden kann, ist die Behauptung unfalsifizierbar. Wo sie doch einmal prüfbar gemacht wurde, hielt sie nicht: Jacques Benveniste meldete 1988 in „Nature“, extrem verdünnte Antikörper wirkten noch auf weiße Blutzellen, doch bei der Nachprüfung verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Dazu kommt, dass Wasserstoffbrücken zwischen Wassermolekülen sich im Femto- bis Pikosekundenbereich bilden und lösen, Struktur in Flüssigkeiten ist also extrem kurzlebig.","coreRule":"⚡ Eine Zusatzannahme, die nur den Widerspruch abfängt und sich nicht prüfen lässt, ist noch keine Erklärung.","beleg":"Werkstück G.3.2 (Kernidee; Kontext & Tiefe; Verbindungen); Fn. gl-g-5 (Roth 2013, Chemie in unserer Zeit 47, S. 111)","status":"entwurf","scenario":"Eine Kundin fragt in einer Apotheke, wie ein Mittel in der Potenz C30 wirken soll, wenn rechnerisch kein Molekül des Wirkstoffs mehr enthalten ist. Der Berater antwortet: „Das Wasser hat sich die Information gemerkt. Die Wirkung ist eben immateriell.“","kurz":"Die „Information im Wasser“ wurde nicht beobachtet, sondern erst eingeführt, um den Widerspruch der fehlenden Substanz aufzulösen, und kein Instrument kann sie prüfen. Wo sie doch einmal geprüft wurde, verschwand der Effekt.","prueffrage":"Auf welche Frage der Kundin antwortet der Berater, und welche Beobachtung nennt er als Grundlage für seine Antwort?","rueckmeldung":[{"option":1,"text":"Die Behauptung ist nicht in sich widersprüchlich: Dass Wasser aus Materie besteht, schließt eine behauptete „Information“ darin nicht logisch aus. Das Problem liegt woanders: Sie wurde nur eingeführt, um den Widerspruch aufzulösen, und lässt sich nicht prüfen."},{"option":2,"text":"Von einem „Gedächtnis“ des Wassers zu sprechen, ist tatsächlich ein menschliches Bild. Aber ein Bild ließe sich in einen messbaren Vorgang übersetzen und prüfen. Der eigentliche Mangel ist, dass die Annahme erst nachträglich auftaucht und unprüfbar bleibt."},{"option":3,"text":"Dass die Behauptung unbelegt ist, stimmt, doch sie ist mehr als „bisher“ unbelegt: Sie wurde nur zur Rettung der Wirkung eingeführt, und wo man sie prüfbar machte, verschwand der Effekt bei verblindeter Auswertung. Ein Messverfahren allein machte sie noch nicht zur Erklärung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"},{"typ":"doi","kurz":"Roth, K. (2013): Vitalisiert, verwirbelt, levitiert, energetisiert, informiert und anti-entropisch H2O – Jo mei! Chemie in unserer Zeit 47, 108–121","oeffentlich":false,"doi":"10.1002/ciuz.201300626"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"16e0e2e98a6658c3"}},{"id":"qx-g-038","clusterId":"G","werkstueckRef":"G.3.2","stufe":4,"question":"Was ist an dieser Gesprächsführung des Anbieters fehlerhaft?","scenario":"Eine Anzeige für ein „informiertes“ Trinkwassergerät verspricht, es speichere „positive Schwingungen“. Auf die Frage nach einem Messverfahren heißt es: „Die Wirkung ist feinstofflich – du denkst zu materialistisch.“","options":["Er verspricht eine Wirkung, ohne einen prüfbaren Mechanismus zu nennen, und weicht der Nachfrage mit einem Spruch aus.","Er wird persönlich und hält der fragenden Person ihre Denkweise vor; sachlich vorgebracht wäre seine Antwort in Ordnung.","Er weicht aus, statt zu erklären, warum sich eine feinstoffliche Wirkung mit üblichen Messgeräten nicht erfassen lässt.","Er geht auf die Nachfrage nicht ein, statt anzubieten, das Gerät zu testen, damit man die Wirkung selbst spüren kann."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist nur dann prüfbar, wenn sie sagt, wie die Wirkung zustande kommen soll und woran man sie messen könnte. „Positive Schwingungen“ werden ohne Speicher- und Abrufmechanismus versprochen und als „feinstofflich“ beschrieben, damit sie sich jeder Messung entziehen. Auf die berechtigte Nachfrage kommt kein Beleg, sondern ein Spruch: „Du denkst zu materialistisch“ ist ein Gedanken-stoppendes Klischee, das die Frage abwürgt, statt sie zu beantworten. Genau diese Antwort ist ein typisches Warnsignal der „Wassergedächtnis“-Rhetorik. Das Muster lässt sich so anwenden: Wer eine Wirkung behauptet, trägt die Beweislast und muss zeigen, wie sich die Wirkung nachweisen lässt. Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand. Fehlerhaft im Kern ist, dass Mechanismus und Messbarkeit verweigert und die Behauptung so gegen Prüfung abgeschirmt wird.","coreRule":"⚡ Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand.","beleg":"Werkstück G.3.2 (Red Flags)","status":"entwurf","kurz":"Eine Wirkbehauptung ist nur prüfbar, wenn sie Mechanismus und Messbarkeit nennt. „Feinstofflich“ und „du denkst zu materialistisch“ weichen der berechtigten Nachfrage aus und schirmen die Behauptung gegen jede Prüfung ab.","prueffrage":"Woran könnte man hier überhaupt feststellen, ob das Gerät etwas bewirkt oder nicht?","rueckmeldung":[{"option":1,"text":"Der persönliche Seitenhieb ist tatsächlich ein Schwachpunkt. Auch höflich vorgebracht bliebe die Antwort aber leer: Sie nennt weder Mechanismus noch Messbarkeit. Der Kern liegt in der Abschirmung der Behauptung, nicht im Ton."},{"option":2,"text":"Das Ausweichen stimmt. Die Option setzt jedoch voraus, dass die Wirkung real, aber nur mit üblichen Geräten nicht messbar sei. Das ist gerade die Behauptung, die zu belegen wäre. Eine Erklärung, warum sich nichts messen lässt, würde sie nur weiter abschirmen."},{"option":3,"text":"Ein Selbsttest wirkt entgegenkommend, beweist aber nichts. Was man „spürt“, kann von Erwartung und Suggestion kommen, auch wenn das Gerät nichts bewirkt. Er ersetzt weder einen Mechanismus noch ein Messverfahren."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8cb9abf4e1f37b87"}},{"id":"qx-g-039","clusterId":"G","werkstueckRef":"G.3.3","stufe":1,"question":"Du liest die Aussage: „Ich setze auf natürliche Immunität statt auf Impfung.“ Was leistet das Wort „natürlich“ in diesem Satz vor allem?","options":["Es lässt die Infektion als reinen, ursprünglichen Weg erscheinen und blendet die Risiken der Krankheit dabei einfach aus.","Es benennt einen echten Unterschied: Bei der Infektion baut der Körper den Schutz selbst auf, ohne fremde Stoffe von außen.","Es verweist auf Bewährung: Was natürlich ist, hat sich über lange Zeit erprobt, und das macht diesen Weg vertrauenswürdig.","Es dient vor allem dazu, die Impfung als künstlichen Eingriff abzuwerten, und sagt über die Infektion selbst kaum etwas."],"correctIndex":0,"explanation":"Das Wort „natürlich“ weckt ein positives Gefühl (Appell an die Natur): Die Infektion wirkt wie ein reiner, ursprünglicher Prozess, die Impfung wie ein künstlicher Eingriff in ein „perfektes“ Immunsystem. Das Narrativ konzentriert sich nur auf das Ergebnis (Immunität) und blendet den Prozess, die potenziell tödliche Krankheit, aus. Dass „natürlich“ nicht „besser“ heißt, zeigt Tetanus: Bei Tetanus führt die Infektion zu keiner Immunität, die Impfung schon. Bei HPV erzeugt die Impfung eine stärkere und verlässlichere Immunantwort als die Infektion. Ob ein Weg gut ist, entscheiden Risiken und Schutz, nicht der Klang des Wortes.","coreRule":"⚡ „Natürlich“ ist ein Gefühlswort und kein Qualitätsnachweis.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Appell an die Natur; Red Flags: Herdenimmunität)","status":"entwurf","scenario":"In einer Diskussion über Impfungen sagt jemand: „Ich setze lieber auf die natürliche Immunität. Das ist der echte Weg, nicht dieser künstliche Eingriff.“","kurz":"„Natürlich“ weckt ein gutes Gefühl und lässt die Infektion rein und ursprünglich wirken, während die gefährliche Krankheit dahinter unsichtbar bleibt. „Natürlich“ heißt aber nicht „besser“: Bei Tetanus schützt nur die Impfung.","prueffrage":"Wie wirkt der Satz, wenn man „natürliche Immunität“ durch „Immunität nach Ansteckung“ ersetzt?","rueckmeldung":[{"option":1,"text":"Dass der Körper den Schutz bei der Infektion selbst aufbaut, stimmt. Daraus folgt aber keine bessere Wahl, denn Tetanus verleiht keine Immunität. Das Wort beschreibt hier nicht neutral, es wertet auf und lässt die Krankheit aus."},{"option":2,"text":"Lange Bewährung klingt nach einem Gütesiegel. Beim Infektionsweg hieße das aber, die Krankheit mit ihren Risiken gleich mitzuverteidigen. Ein Beleg für guten Schutz ist das nicht, bei Tetanus entsteht durch die Infektion gar keine Immunität."},{"option":3,"text":"Dass die Impfung als „künstlich“ abgewertet wird, stimmt. Das ist aber nur die eine Hälfte: Dasselbe Wort wertet zugleich die Infektion auf, indem sie rein und ursprünglich wirkt und ihr Risiko aus dem Blick gerät."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"2a7fee2e535bb17a"}},{"id":"qx-g-040","clusterId":"G","werkstueckRef":"G.3.3","stufe":2,"question":"Was ist an dieser Argumentation grundlegend falsch?","scenario":"In einer Diskussion über Impfungen sagt jemand: „Wer Tetanus durchmacht, hat danach natürliche Immunität. Das ist doch der beste Weg, die Impfung brauche ich nicht.“ Du weißt: Das Tetanus-Toxin ist schon in winzigen Mengen tödlich, und eine überstandene Erkrankung hinterlässt keinen Schutz vor einer neuen Ansteckung.","options":["Sie setzt voraus, dass eine überstandene Tetanus-Erkrankung vor neuer Ansteckung schützt, obwohl sie keine Immunität hinterlässt und schon wenig Gift tödlich sein kann.","Sie verwechselt „natürlich“ mit „harmlos“ und übersieht, dass schon winzige Mengen des Tetanus-Gifts tödlich sein können, sodass schon die Erkrankung selbst das Risiko ist.","Sie folgert ohne Begründung aus „natürlich“ auf „am besten“; das ist ein Werturteil, über das sich mit Tatsachen zur Krankheit allein kaum entscheiden lässt.","Sie stützt sich auf eine unbelegte Behauptung, denn die Person nennt für die natürliche Immunität keine Quelle, sodass man ihr ohne eigene Prüfung nicht folgen sollte."],"correctIndex":0,"explanation":"Das Argument setzt stillschweigend voraus, dass „natürlich“ zugleich „besser“ heißt und dass eine Erkrankung überhaupt Schutz hinterlässt. Beides lässt sich prüfen: Tetanus-Gift ist so stark, dass schon winzige Mengen (geschätzte minimale tödliche Dosis: 2,5 Nanogramm je Kilogramm Körpergewicht) tödlich wirken können. Laut CDC hinterlässt die Erkrankung keine Tetanus-Immunität. Wer sie überlebt, ist deshalb nicht geschützt; nach der Erkrankung soll die Impfung beginnen oder fortgesetzt werden, sobald sich der Zustand stabilisiert hat (CDC). Die Impfung bringt den Schutz, den die Infektion nicht liefert. Bei HPV ist die natürliche Immunität zwar vorhanden, aber schwächer als die Impf-Immunität; bei Tetanus entsteht sie gar nicht. Ob Infektion oder Impfung besser schützt, muss man pro Krankheit prüfen.","coreRule":"⚡ „Natürlich“ heißt nicht „besser“: Prüfe pro Krankheit, ob die Infektion überhaupt schützt, und was der Weg dorthin kostet.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-2 (CDC, Pink Book, 14. Aufl. 2021, Kap. 21)","status":"entwurf","kurz":"Das Argument nimmt an, die Erkrankung hinterlasse Schutz. Tetanus schützt aber nicht vor einer neuen Ansteckung, und schon wenig Gift kann tödlich wirken. „Natürlich“ wird zu „am besten“, ohne dass das geprüft wird.","prueffrage":"Was bleibt nach einer überstandenen Tetanus-Erkrankung an Schutz zurück, und wie riskant ist der Weg dorthin?","rueckmeldung":[{"option":1,"text":"Dass „natürlich“ nicht „harmlos“ heißt und schon wenig Gift tödlich sein kann, stimmt. Der Kern liegt aber woanders: Selbst wer die Erkrankung überlebt, ist danach nicht geschützt."},{"option":2,"text":"Der Schritt von „natürlich“ zu „am besten“ ist wirklich ungeprüft. Er lässt sich aber an Tatsachen messen, etwa an Schutzwirkung und Gefahr der Krankheit, und genau daran scheitert die Behauptung."},{"option":3,"text":"Eine Quelle zu vermissen ist berechtigt. Der Mangel ist hier aber größer: Die Behauptung ist nicht bloß unbelegt, sondern sachlich falsch, weil Tetanus keine Immunität hinterlässt."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ee76a4a7548cfcf3"}},{"id":"qx-g-041","clusterId":"G","werkstueckRef":"G.3.3","stufe":3,"question":"Welche Antwort an Jonas wird den beiden Fällen gerecht?","options":["Mira und Lars haben nach ihrer Krankheit beide keinen Schutz; „immer besser“ scheitert bei beiden am völligen Fehlen von Immunität.","Mira und Lars haben nach ihrer Krankheit beide einen Teilschutz, der schwächer ist als der Impfschutz; „immer besser“ scheitert bei beiden daran.","Mira hat nach ihrer Krankheit keinen Schutz, Lars einen, der schwächer ist als der Impfschutz; „immer besser“ trifft auf keinen der beiden zu.","Mira hat nach ihrer Krankheit keinen Schutz, Lars einen, der stärker ist als der Impfschutz; „immer besser“ trifft also nur auf Lars zu."],"correctIndex":2,"explanation":"„Die“ natürliche Immunität gibt es nicht; sie fällt je nach Krankheit sehr unterschiedlich aus, und genau das zeigen Mira und Lars. Tetanus hinterlässt laut CDC keine Immunität; der Grund ist die extreme Giftigkeit des Toxins (die geschätzte minimale tödliche Dosis liegt bei 2,5 Nanogramm je Kilogramm Körpergewicht). Mira ist also trotz überstandener Krankheit ungeschützt und soll geimpft werden. Lars hat nach seiner HPV-Infektion zwar Antikörper gebildet, aber langsam, unvollständig und typspezifisch; die Impfung erzeugt deutlich höhere Spiegel (in einer Übersicht 3.000–10.000 mMU/mL gegenüber 100–500 mMU/mL nach natürlicher Ansteckung), und der Impfschutz hält nach bisherigen Daten über ein Jahrzehnt an. Jonas’ „immer besser“ scheitert also an beiden, aber aus verschiedenen Gründen. Bei beiden „keinen Schutz“ anzunehmen übersieht die Antikörper von Lars, bei beiden einen „Teilschutz“ anzunehmen übersieht, dass Tetanus gar keinen hinterlässt. Einen stärkeren Schutz als die Impfung hat Lars nicht, denn das Merkblatt nennt für die Impfung die deutlich höheren Werte.","coreRule":"⚡ Pauschalaussagen wie „natürlich ist immer besser“ prüfst du Krankheit für Krankheit: Mal fehlt der natürliche Schutz ganz, mal ist er nur schwächer als der Impfschutz.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-3 (Ghilencea u. a. 2026, Antibodies 15(4), 61)","status":"entwurf","scenario":"Jonas sagt in einer Diskussion: „Natürliche Immunität ist immer besser als eine Impfung.“ Als Beispiele nennt er Mira, die vor einem Jahr Tetanus überstanden hat, und Lars, der eine HPV-Infektion hinter sich hat. In einem ärztlichen Merkblatt, das ihr gemeinsam lest, steht: Tetanus hinterlässt keine Immunität, weil schon eine winzige Giftmenge tödlich sein kann; deshalb wird auch nach überstandener Krankheit geimpft. Nach einer HPV-Infektion bildet der Körper Antikörper, aber langsam, unvollständig und nur gegen den jeweiligen Virustyp; die Impfung erzeugt deutlich höhere Antikörperspiegel (etwa 3.000–10.000 statt 100–500 mMU/mL).","kurz":"„Natürliche Immunität“ gibt es nicht pauschal: Tetanus hinterlässt keine, bei HPV entstehen nur schwächere Antikörper als durch die Impfung. Der Fehler wäre, beide Fälle über einen Kamm zu scheren, obwohl der Ausgang je nach Krankheit anders ist.","prueffrage":"Was steht im Merkblatt über die Antikörper nach überstandener Krankheit, und gilt das für beide Fälle gleich?","rueckmeldung":[{"option":0,"text":"Bei Mira stimmt das, denn Tetanus hinterlässt keine Immunität. Bei Lars passt es nicht: Nach der HPV-Infektion hat sein Körper Antikörper gebildet, wenn auch langsam, unvollständig und nur gegen einen Virustyp."},{"option":1,"text":"Für Lars trifft das zu: Seine Antikörper sind messbar, aber deutlich niedriger als nach einer Impfung. Bei Mira nicht, denn Tetanus hinterlässt laut Merkblatt gar keine Immunität, also auch keinen Teilschutz."},{"option":3,"text":"Bei Mira stimmt das. Dass Lars die Impfung übertrifft, lässt sich aus den Zahlen des Merkblatts aber nicht ablesen: Dort stehen für die Impfung deutlich höhere Antikörperspiegel (3.000–10.000 statt 100–500 mMU/mL). Auch bei Lars scheitert „immer besser“."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV: A Comparative Review of Antibody Response and Cancer Prevention. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8421cec97f1ad5d7"}},{"id":"qx-g-042","clusterId":"G","werkstueckRef":"G.3.3","stufe":4,"question":"Welche Schlussfolgerung ist angemessen?","options":["Der hohe Schutz gilt nur für Menschen, die die Infektion überlebt haben; Tote und Komplikationen auf dem Weg dorthin fehlen in den Zahlen.","Die Aussage ist gut gestützt; 65 Studien bilden eine breite Grundlage, und mehr als 78 Prozent Schutz vor schwerem Verlauf sind ein hoher Wert.","Beobachtungsstudien können Störfaktoren enthalten; ohne kontrollierte Versuche lässt sich über den Schutz nach einer Infektion kaum etwas sagen.","Der Sprecher übersieht vor allem den zweiten Wert: 45 Prozent Schutz vor Ansteckung heißt, dass sich mehr als die Hälfte der Genesenen erneut ansteckt."],"correctIndex":0,"explanation":"Die Zahlen beschreiben den Schutz derjenigen, die die Infektion überlebt haben. Wer daran gestorben ist, taucht in dieser Gruppe nicht auf, und was die erste Erkrankung an Komplikationen gekostet hat, steckt in keiner der Prozentzahlen: Das ist die Perspektive des Überlebensirrtums. Der hohe Schutz vor schwerem Verlauf ist real, wurde aber mit der Krankheit selbst bezahlt, und vor erneuter Ansteckung schützte die Infektion deutlich schlechter. Dass Beobachtungsstudien Störfaktoren enthalten können, mindert die Aussagekraft, macht sie aber nicht wertlos. Wer Wege vergleicht, muss deshalb auch die Kosten des Weges betrachten und nicht nur das Ergebnis am Ziel.","coreRule":"⚡ Ein Schutz, der mit der Krankheit bezahlt wird, ist nicht umsonst, auch wenn er hoch ist.","beleg":"Werkstück G.3.3 (Anwendung & Relevanz: COVID-19-Pandemie; Verbindungen: Überlebensirrtum); Fn. gl-g-reinfektion (COVID-19 Forecasting Team 2023, The Lancet 401, S. 833 und 841)","status":"entwurf","scenario":"Eine Auswertung von 65 Beobachtungsstudien zeigt: Menschen, die eine COVID-19-Infektion überstanden hatten, waren später zu mehr als 78 Prozent vor schwerem Verlauf geschützt, vor erneuter Ansteckung mit Omikron BA.1 aber nur zu rund 45 Prozent. Jemand sagt dazu: „Da seht ihr es: Wer die Krankheit durchmacht, ist hinterher bestens geschützt. Die Impfung brauche ich nicht.“","kurz":"Die Prozentzahlen beschreiben nur Menschen, die die Infektion überstanden haben. Wer daran starb oder Komplikationen erlitt, fehlt in der Zahl. Der Schutz ist real, wurde aber mit der Krankheit bezahlt, und diese Kosten des Weges bleiben unsichtbar.","prueffrage":"Wovor schützte die überstandene Infektion laut den Zahlen gut, wovor weniger gut, und was macht die Person daraus?","rueckmeldung":[{"option":1,"text":"Viele Studien und ein hoher Schutzwert wirken überzeugend, und am Wert selbst ist nichts falsch. Aber auch viele Studien messen nur diejenigen, die die Infektion hinter sich haben. Was der Weg dorthin gekostet hat, steckt in keiner Prozentzahl."},{"option":2,"text":"Störfaktoren sind bei Beobachtungsstudien tatsächlich ein Thema. Daraus folgt aber nicht, dass man kaum etwas sagen kann: Die Aussagekraft sinkt, die Daten sind nicht wertlos. Das eigentliche Problem liegt an anderer Stelle, nämlich bei der Frage, wer in den Zahlen überhaupt vorkommt."},{"option":3,"text":"Der zweite Wert ist wichtig: Gegen erneute Ansteckung schützte die Infektion deutlich schlechter, und das blendet der Sprecher aus. Dieser Einwand erreicht aber nicht den Kern. Auch bei beiden Zahlen fehlen alle, die die erste Erkrankung nicht gut überstanden haben."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"COVID-19 Forecasting Team (2023): Past SARS-CoV-2 infection protection against re-infection: a systematic review and meta-analysis. The Lancet 401(10379), 833–842","oeffentlich":true,"doi":"10.1016/S0140-6736(22)02465-5","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9998097/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9ed591cbca3b505a"}}]`);export{t as n,n as t};